Object.assign(window.__SYN,{"c:数+弦+大": {"o": "弦大数脉总属邪热炽盛、肝火亢盛之象，但须分虚实。弦为肝脉，主气郁、风动；大为邪盛或虚阳外张；数为热盛或病进。实者多见于肝火、热盛、风痰、湿热、热毒，脉来有力，症见壮热、烦躁、目赤、抽搐、肿痛等；虚者多见于阴虚火旺、虚阳上浮，脉虽弦大数而按之无力，症见形瘦、潮热、失音、便艰等。此外，久病见弦大数多示病进，预后不良。各类之间可相互转化，如肝火可化风、灼津为痰，湿热可酿毒，虚火可致阳浮，总以脉症合参辨其虚实。", "c": [{"name": "主肝火", "desc": "弦为肝脉，大数为火盛。原文多见弦大而数，如“气有余便是火”、“木郁生火，肝火散越”、“肝家郁火”，症见头目昏晕、咽中热冲、目赤肿痛、胁痛等，皆肝经郁热化火上攻之象。"}, {"name": "主热盛", "desc": "数脉主热，大主邪盛。原文如暑温“热势反剧”、“阳明湿热”、“暑热客邪迫血妄行”，症见壮热、口渴、舌绛、便闭等，脉弦大数示邪热炽盛、充斥表里。"}, {"name": "主虚火", "desc": "弦大为阴不敛阳，数为虚火。原文如“阴液枯涸，木火犯肺”、“精血枯痿，冲阳上逆”、“阴损阳浮”，症见形瘦骨立、潮热、失音、便艰，脉虽弦大数而按之无力，为阴虚阳浮之候。"}, {"name": "主风痰", "desc": "弦主肝风，大数主痰火。原文如“肝风挟痰，中于府络”、“风火内旋”、“化热生风”，症见偏瘫、口眼歪斜、抽搐、神昏，脉弦大数示风火痰热内扰。"}, {"name": "主湿热", "desc": "弦主湿郁，数主热，大示邪盛。原文如“脾经伏热，湿邪下陷”、“阳明湿热挟胆经风阳上逆”、“暑湿滞深重”，症见浮肿、胸闷、苔厚黄、头痛，脉弦大数示湿热壅盛。"}, {"name": "主热毒", "desc": "弦为肝胆，大数主热毒炽盛。原文如“肝胆二经有热毒”、“热毒蕴结肝胆”，症见胁下红块硬痛、目赤肿痛，脉弦大数示热毒壅结、痰瘀互结。"}], "n": {"主肝火": 11, "主热盛": 6, "主虚火": 13, "主风痰": 4, "主湿热": 4, "主热毒": 2}, "a": {"278": "主虚火", "555": "主肝火", "1167": "主虚火", "1386": "主肝火", "2417": "主风痰", "2456": "主热盛", "3900": "主肝火", "3995": "主肝火", "4367": "主肝火", "4680": "主湿热", "5932": "主湿热", "5959": "主肝火", "6236": "主热毒", "6529": "主热毒", "7238": "主风痰", "7312": "主风痰", "7647": "主虚火", "7709": "主热盛", "8501": "主虚火", "9192": "主湿热", "10404": "主肝火", "10753": "主湿热", "11242": "主虚火", "11385": "主肝火", "11389": "主肝火", "11396": "主肝火", "11504": "主虚火", "12527": "主虚火", "13131": "主虚火", "14904": "主热盛", "15946": "主风痰", "16317": "主虚火", "16579": "主热盛", "18584": "主热盛", "18590": "主热盛", "18597": "主肝火", "22673": "主虚火", "23755": "主虚火", "24312": "主虚火", "26892": "主虚火"}, "t": 40, "np": 0}, "c:弦+硬": {"o": "弦硬脉总起来主肝火亢盛、阴亏失柔、气逆上冲、胃气衰败、木乘土位及痰热瘀滞等病机。其核心在于“弦主肝，硬主劲急”，反映肝木刚劲失和、气机升降失常。肝火亢盛与阴亏失柔常互为因果：火盛灼阴，阴亏则木失濡养，脉更弦硬；气逆上冲多由肝火挟冲胃之气上逆，血随气升，甚则昏厥；胃气衰败乃真脏脉见，为危候；木乘土位则肝胃同病，症见胀满泄泻；痰热瘀滞则脉道壅塞，兼见痰血癥瘕。诸类之间，或虚实夹杂，或标本相兼，总以肝木失调为枢机，临证须结合部位、兼脉及症候，辨其寒热虚实。", "c": [{"name": "主肝火亢盛", "desc": "弦硬脉为肝火炽盛、木火上逆之象。弦主肝，硬主劲急亢盛，故见脉弦硬多示肝火偏亢，如原文“左关弦硬，相火上炎，防吐血复发”“脉形弦硬，为木火亢盛、肝阳上逆之象”。火性急迫，故脉失柔和而硬，常见眩晕、头痛、吐血、烦躁等症。"}, {"name": "主阴亏失柔", "desc": "弦硬脉亦主阴液亏虚、木失柔养。原文谓“弦硬为肝肾阴亏、木失柔养”“弦硬即有阴亏之象”，阴血不足则脉道失濡，肝木刚劲不柔，故脉弦硬。常见于失血、久病、温邪伤阴之后，症见舌赤无津、便燥、不寐等。"}, {"name": "主气逆上冲", "desc": "弦硬脉主气机逆乱、有升无降。弦主肝，硬主劲急，长主气逆有余，故脉弦硬而长多示肝胃冲气上逆，血随气升，充塞脑部。原文“左右皆弦硬而长，为肝阳上亢、气血上冲脑部之象”，症见头疼、眩晕、昏厥、半身不遂等。"}, {"name": "主胃气衰败", "desc": "弦硬脉见真脏之象，主胃气衰败、真阴耗竭。原文“脉象弦硬，此系孤阳反照”“弦硬为胃气败绝、真阴耗竭之候”，春令见弦硬为“但弦无胃”，失冲和胃气。症见纳食哽痛、大便坚燥、形神衰惫，预后不良。"}, {"name": "主木乘土位", "desc": "弦硬脉主肝木乘脾克胃，肝胃不和。原文“右部弦硬异常，按之甚实，为肝木乘土之象”“左关弦硬乃肝郁乘脾”，肝气郁滞，横逆犯中，脾胃受克，症见腹疼、泄泻、胀闷、纳呆等。"}, {"name": "主痰热瘀滞", "desc": "弦硬脉主痰热内蕴、瘀血阻滞。原文“脉弦硬或弦而兼数，为阴血伤损、内热瘀滞之征”“弦硬主瘀滞与内热”，痰热瘀血交阻，脉道不利，故脉弦硬。常见咳逆痰血、胸胁刺痛、癥瘕等症。"}], "n": {"主肝火亢盛": 33, "主阴亏失柔": 20, "主气逆上冲": 17, "主胃气衰败": 8, "主木乘土位": 10, "主痰热瘀滞": 7}, "a": {"499": "主胃气衰败", "1633": "主木乘土位", "7598": "主阴亏失柔", "8062": "主木乘土位", "10477": "主气逆上冲", "10491": "主木乘土位", "10531": "主肝火亢盛", "10792": "主肝火亢盛", "10909": "主木乘土位", "13124": "主阴亏失柔", "13306": "主胃气衰败", "13531": "主痰热瘀滞", "13576": "主痰热瘀滞", "13618": "主阴亏失柔", "13680": "主胃气衰败", "13733": "主阴亏失柔", "14048": "主胃气衰败", "14342": "主胃气衰败", "14585": "主痰热瘀滞", "14666": "主痰热瘀滞", "14676": "主胃气衰败", "14807": "主胃气衰败", "14868": "主阴亏失柔", "14934": "主肝火亢盛", "15483": "主木乘土位", "15661": "主痰热瘀滞", "15725": "主木乘土位", "15745": "主木乘土位", "15823": "主肝火亢盛", "16134": "主木乘土位", "19502": "主气逆上冲", "19601": "主气逆上冲", "19808": "主气逆上冲", "19868": "主肝火亢盛", "19913": "主肝火亢盛", "19918": "主木乘土位", "20068": "主肝火亢盛", "20183": "主气逆上冲", "20193": "主痰热瘀滞", "20252": "主气逆上冲", "20272": "主肝火亢盛", "20273": "主肝火亢盛", "20349": "主阴亏失柔", "20378": "主肝火亢盛", "20381": "主肝火亢盛", "20404": "主阴亏失柔", "20406": "主阴亏失柔", "20407": "主阴亏失柔", "20408": "主阴亏失柔", "20423": "主肝火亢盛", "20424": "主肝火亢盛", "20440": "主气逆上冲", "20449": "主阴亏失柔", "20450": "主气逆上冲", "20454": "主气逆上冲", "20469": "主气逆上冲", "20471": "主肝火亢盛", "20475": "主气逆上冲", "20480": "主阴亏失柔", "20482": "主气逆上冲", "20483": "主肝火亢盛", "20488": "主肝火亢盛", "20489": "主肝火亢盛", "20490": "主肝火亢盛", "20505": "主肝火亢盛", "20517": "主肝火亢盛", "20527": "主肝火亢盛", "20530": "主胃气衰败", "20546": "主阴亏失柔", "20552": "主木乘土位", "20556": "主阴亏失柔", "20557": "主阴亏失柔", "20560": "主肝火亢盛", "20561": "主肝火亢盛", "20562": "主肝火亢盛", "20563": "主肝火亢盛", "20564": "主肝火亢盛", "20566": "主肝火亢盛", "20580": "主气逆上冲", "20581": "主气逆上冲", "20613": "主肝火亢盛", "20640": "主阴亏失柔", "20641": "主阴亏失柔", "20642": "主阴亏失柔", "20656": "主肝火亢盛", "20657": "主肝火亢盛", "20660": "主肝火亢盛", "20661": "主肝火亢盛", "20669": "主阴亏失柔", "20683": "主气逆上冲", "20684": "主气逆上冲", "20711": "主气逆上冲", "20716": "主肝火亢盛", "20763": "主阴亏失柔", "22789": "主痰热瘀滞"}, "t": 95, "np": 0}, "pc:左+弦+涩": {"o": "左弦涩脉总以肝郁气滞与血少涩滞为基本病机。弦为肝气偏旺、气机郁滞，涩为血行不畅、阴血亏少。二者并见，多示气滞血瘀、血虚肝旺之候。其具体所主，约分七类：肝郁气滞、血虚阴亏、血瘀积滞、木火刑金、脾虚湿困、寒凝气滞、痰饮内停。诸类之间常相互兼夹：肝郁气滞可横逆犯胃而致脾虚湿困，郁久化火则木火刑金；血虚阴亏可致脉道涩滞而成血瘀，瘀阻又可加重气滞；寒凝、痰饮亦每与气滞血瘀并存。要之，弦涩脉不离“气滞”与“血少/血瘀”两端，其病位多在肝、脾、胃、肺，病性多属虚实夹杂，以肝郁气滞为标，阴血亏虚为本，治当疏肝理气、养血活血，兼顾他脏。", "c": [{"name": "主肝郁气滞", "desc": "左弦为肝气偏旺、气机郁滞，涩为气行不畅。原文多见胸胁胀痛、嗳气泛恶、脘腹联痛、脉左弦右涩等，如言肝气横逆、犯胃克脾，直断气火不降，谓肝气不疏，皆以弦涩示肝郁气滞之机。"}, {"name": "主血虚阴亏", "desc": "涩主血少、脉道不充，弦为肝用偏亢。原文见经闭纳少、舌光无苔、失血久耗、心悸怵惕等，如血室干枯、涩为血少、失血五年阴血久耗、心营暗耗，皆以左弦涩示阴血亏虚、肝失濡养之病机。"}, {"name": "主血瘀积滞", "desc": "涩主血行滞涩、瘀阻络脉，弦主气滞。原文见经阻、瘕块、少腹攻逆、痛连少腹等，如血蛊症、厥阴滞积、肝气疝瘕、产后瘕泻，皆以弦涩示气滞血瘀、凝聚有形之病机。"}, {"name": "主木火刑金", "desc": "左弦为木火偏亢，涩为阴血枯涸，木火上升刑金。原文见咳嗽、音哑、头晕、舌光等，如木火刑金、肝风烁肺、郁极化火上冲，皆以弦涩示肝火偏亢、阴血不足、肺金受灼之病机。"}, {"name": "主脾虚湿困", "desc": "右涩为脾运不健、湿滞血少，左弦为肝木偏旺。原文见纳少、便泻、苔腻、肢倦等，如脾胃不和、湿滞血少、木克土便泻，皆以弦涩示肝脾不和、湿浊困阻中焦之病机。"}, {"name": "主寒凝气滞", "desc": "弦主寒、主痛，涩主气滞血少。原文见寒热、下痢、疝瘕、少腹冷痛等，如寒邪郁滞、寒能生湿、气结血瘀，皆以弦涩示寒邪凝滞、气血不畅之病机。"}, {"name": "主痰饮内停", "desc": "涩主气机不畅，弦主饮邪内动，常兼滑脉。原文见痰多咳逆、胸满胀痛、泛恶等，如湿痰逗留中焦、湿饮内停、痰阻肺气，皆以弦涩示痰饮内停、气机升降失司之病机。"}], "n": {"主肝郁气滞": 11, "主血虚阴亏": 8, "主血瘀积滞": 4, "主木火刑金": 2, "主脾虚湿困": 2, "主寒凝气滞": 1, "主痰饮内停": 1}, "a": {"276": "主木火刑金", "392": "主血虚阴亏", "398": "主肝郁气滞", "400": "主肝郁气滞", "404": "主血瘀积滞", "439": "主血虚阴亏", "456": "主肝郁气滞", "1395": "主肝郁气滞", "1682": "主肝郁气滞", "1727": "主血瘀积滞", "1838": "主肝郁气滞", "4477": "主肝郁气滞", "6710": "主寒凝气滞", "8536": "主血虚阴亏", "8540": "主血虚阴亏", "8614": "主肝郁气滞", "10124": "主血虚阴亏", "12340": "主脾虚湿困", "12629": "主血虚阴亏", "12668": "主痰饮内停", "13256": "主肝郁气滞", "13838": "主肝郁气滞", "16879": "主木火刑金", "16924": "主脾虚湿困", "17044": "主血瘀积滞", "17068": "主血瘀积滞", "17073": "主血虚阴亏", "17181": "主血虚阴亏", "17207": "主肝郁气滞"}, "t": 29, "np": 0}, "pc:左+数+大": {"o": "左·数大脉总以数主热、大主邪盛或虚浮为纲，所主病机以热盛为核心，旁及肝郁化火、阴虚火旺、痰热互结、积热内结及虚中夹实。数大见于左脉，左候肝心，故多示肝胆气火偏亢、热邪内陷血室或风热内炽；若见于右脉或两关，则偏于肠胃积热、阳明燥热。然数大非尽实热，水亏火炎、痨虫蚀脏、脾胃不足而心肝火刑者，亦可见数大无伦或大而兼涩代，此即虚中夹实之机。诸类之间，实热与积热、痰热多相兼夹，肝郁化火可致热盛动血，阴虚火旺与虚中夹实常互为因果，临证须合参部位、兼脉及症候，方能辨其虚实。", "c": [{"name": "主热盛", "desc": "数主热，大主邪盛，数大相合为热邪炽盛之象。原文如左数右大主热邪内陷血室，左手数大示冬温热盛，右脉数大主肠胃积热、左脉数大主肝胆积热，皆以数大示实热壅盛。"}, {"name": "主阴虚火旺", "desc": "数大之脉亦可由水亏火炎所致，非尽实热。原文左脉数大，清火消痰不应，断为水亏无制火，两尺沉数主肾水燥竭，左脉数大无伦为痨虫蚀脏、邪热嚣张而本虚，皆示阴亏虚火上炎之机。"}, {"name": "主痰热互结", "desc": "数主热，大主邪实，痰热交结亦见数大或滑数。原文脉多数大或滑数，右数大主燥火伤气、左滑数主燥火伤血，气口滑大为胃消痰热，浮大弦数为气火郁勃、痰火内扰，皆痰热壅盛之征。"}, {"name": "主积热内结", "desc": "数大主热积内壅，见于三消、泄泻、小便不利等。原文右数大肠胃积热、左数大肝胆积热，右脉数大示肠胃积热壅盛，右数大主阳明燥热、左数大属少阴热移，皆积热内结之脉。"}, {"name": "主虚中夹实", "desc": "数大之中兼见虚象，或大而无力、无绪，示本虚标实。原文两关大数而寸尺和弱，示中焦有热、本元不足；脉大无绪为邪热鸱张、气血紊乱；急大而数时一代涩，为脾胃不足而心肝火刑；左数大无伦而右沉缓无力，皆虚中夹实。"}], "n": {"主热盛": 11, "主阴虚火旺": 1, "主痰热互结": 1, "主积热内结": 2, "主虚中夹实": 3}, "a": {"1172": "主热盛", "2192": "主热盛", "3094": "主虚中夹实", "6110": "主热盛", "7108": "主热盛", "7287": "主热盛", "8541": "主热盛", "11133": "主热盛", "11280": "主阴虚火旺", "15247": "主虚中夹实", "17384": "主热盛", "18355": "主虚中夹实", "24780": "主痰热互结", "24812": "主热盛", "24910": "主积热内结", "24916": "主热盛", "25024": "主积热内结", "25088": "主热盛"}, "t": 18, "np": 0}, "pc:两+大+洪": {"o": "两·大洪脉总以热盛为核心病机，洪大有力为热邪鼓动气血、脉道充盈之象。其病位有在上焦、在中焦、在表里之异：寸洪大主上焦热壅，关洪大主热瘴，六脉洪大主热毒弥漫。兼滑则痰火互结，兼数则热急，兼尺沉微则上盛下虚、阳亢阴微。诸类皆由热邪炽盛所致，或兼痰、兼虚、兼毒，然总不离‘洪大为热’之纲。", "c": [{"name": "主热盛", "desc": "洪大脉为热邪炽盛、正气抗邪之象。原文多称‘两脉洪大’伴烦渴、躁烦，或‘六脉俱洪大而数’见疮毒内陷，皆因热盛鼓动气血，脉道充盈，故洪大有力。"}, {"name": "主上焦热壅", "desc": "寸脉候上焦，两寸洪大主上焦热盛、气火上逆。原文见胃脘痛、颧红唇红、饮入即吐，或鼻渊头痛、血痢呕吐，皆热壅上焦、胃气上逆或肺热上蒸所致。"}, {"name": "主痰火", "desc": "洪大兼滑主痰火壅盛。原文‘两寸洪大，右关滑大’见吐紫黑血块、足跟焮肿流黄水；或‘两尺洪大，两关滑’断为痰火，皆痰热互结、火性急迫，故脉洪大而滑。"}, {"name": "主上盛下虚", "desc": "洪大见于上部而尺脉沉微，主上焦热盛、下元虚寒，即阳亢阴微、上盛下虚。原文两寸洪大、两尺沉微，症见上热下寒、胃痛吐逆，或痰火在上、肾阴亏于下。"}, {"name": "主热瘴", "desc": "两关洪大主热瘴。原文‘两关脉洪大者，热瘴’，因瘴毒热邪壅遏中焦，气血涌盛，关脉洪大；若洪数按之不实，为阳浮阴闭，热浮于外而阴凝于内。"}], "n": {"主热盛": 4, "主上焦热壅": 4, "主痰火": 2, "主上盛下虚": 6, "主热瘴": 1}, "a": {"2130": "主热盛", "2194": "主热盛", "3829": "主上盛下虚", "4287": "主上盛下虚", "6103": "主上焦热壅", "6109": "主上盛下虚", "6117": "主上焦热壅", "6192": "主痰火", "6194": "主热盛", "6239": "主上盛下虚", "6397": "主上焦热壅", "6403": "主上盛下虚", "6412": "主上焦热壅", "6487": "主痰火", "6489": "主热盛", "6532": "主上盛下虚", "23145": "主热瘴"}, "t": 17, "np": 0}, "c:沉+濡": {"o": "沉濡脉总起来主里虚、湿浊、气陷、阴亏火旺、痰浊、气痹液耗及积滞等多类病机。沉主里、濡主虚，故其核心为虚与湿，可表现为下焦虚寒、脾虚湿困、大气下陷、气弱液耗；虚久则阴亏火旺，水不涵木，厥阳独亢，挟痰浊上蒙清窍；湿浊内蕴又可化热生痰，痰涎壅盛则瘀阻脉道；脾虚湿滞日久则积滞内结。各类之间以虚为本，湿、痰、火、积为标，标本相兼，虚实错杂，故临床须四诊合参，辨其主次。", "c": [{"name": "主虚寒", "desc": "沉濡脉沉主里、濡主虚，多示下焦虚寒、寒湿内侵。如产后寒入，脉沉濡而痛胀、腹鸣晨泄、心痛呕逆，治下为是；大气下陷，左右沉濡，右寸关尤甚，气息下坠、小便不禁、下焦凉甚，皆气虚阳弱之征。"}, {"name": "主湿浊", "desc": "沉濡主湿浊内蕴、脾阳不运。如疟经两月，右脉沉濡，食入便出、腹中隐痛，为正馁邪陷、湿浊困阻；脾脉沉濡，腹胀烦满、不嗜食、食而不化、四肢痹不仁，为脾虚湿困、运化失职。"}, {"name": "主气陷", "desc": "沉濡为气陷不升、脉道不充之象。如喘证脉数兼沉濡，初疑阴虚不纳，然沉濡示大气下陷，故不敢降气，投升陷汤加减而愈；胸中气息下坠、努力呼难上达，脉左右沉濡，亦大气下陷之征。"}, {"name": "主阴亏火旺", "desc": "沉濡可示肾阴亏虚、水不涵木，兼数则火热内炽。如左尺沉濡，寸关弦滑而数，舌红，为少阴水亏、厥阳独亢，引动痰浊上蒙清窍，神机不灵，或类癫或类狂，脉象揭示肾亏肝亢、阴亏火旺。"}, {"name": "主痰浊", "desc": "沉濡为痰涎壅盛、瘀阻脉道之象。如妇人悲泣过度，痰涎杜塞胃口，胃气上逆干呕，左手沉濡、右三部皆无，面有红光、不受生姜，属热痰杜塞，用生白矾化热痰而愈，证明脉象乃痰多瘀脉。"}, {"name": "主气痹液耗", "desc": "沉濡主气弱液耗、脉道不充，气机郁滞。如关格，食少欲吐、吞酸吐沫、脘痛胀、便艰粪如羊矢，脉左右沉濡，为气痹液耗、关格不通之象，用药不可偏阴偏阳，拟和降调中。"}, {"name": "主积滞", "desc": "沉濡属脾虚湿滞，与弦细合参为肝郁脾弱、积滞内结。如胃脘停积数年，渐大如拳甚硬，不能饮食，左脉弦细、右脉沉濡，为肝郁脾弱、积滞内结，用消积扶正之剂而积全消。"}, {"name": "主脏气败绝", "desc": "脉见屋漏、雀啄、弹石、解索等怪脉，无胃气柔和之象，示脏气败绝、真元离散，主死候。"}, {"name": "主毒邪壅盛", "desc": "蛊毒为患，脉随毒种而异，洪壮为热毒壅盛，浮滑而短为毒邪偏表兼痰湿壅滞，总以毒邪壅盛为主。"}], "n": {"主虚寒": 1, "主湿浊": 2, "主气陷": 3, "主阴亏火旺": 2, "主痰浊": 1, "主气痹液耗": 1, "主积滞": 1, "主脏气败绝": 1, "主毒邪壅盛": 1}, "a": {"262": "主阴亏火旺", "263": "主阴亏火旺", "1800": "主虚寒", "11312": "主湿浊", "17742": "主气痹液耗", "19437": "主气陷", "19471": "主气陷", "19531": "主痰浊", "19966": "主积滞", "20421": "主气陷", "21536": "主湿浊", "21823": "主脏气败绝", "22243": "主毒邪壅盛"}, "t": 13, "np": 0}, "pc:右+数+虚": {"o": "右·数虚脉总以虚为本、数为标，主正气亏虚而兼虚热内扰。其虚或为气阴两伤，或为脾胃虚弱，或为营液内耗，或为气血俱虚；其数则示虚热、余热或营热。各段所主虽异，然皆不离'虚数'二字：虚在气分则右脉虚，虚在营血则左脉数；虚在脾胃则右脉虚数，虚在肝肾则左脉虚数。虚热相合，或耗津液，或动肝风，或扰营络，或损脾胃，总属正虚邪少、虚热内生之候。故其病机类别虽分虚热、气阴两虚、脾虚胃弱、营液内耗、肝阳化风、气血俱虚，实皆以虚为根，以数为热，虚热相因为患。", "c": [{"name": "主虚热", "desc": "脉虚数并见，虚为正气不足，数为虚热内扰。原文如'右脉虚数，已属损怯之象'、'脉右虚数，暮微寒热'，皆示气阴两伤、余热未清，故主虚热。"}, {"name": "主气阴两虚", "desc": "右脉虚小或虚细，左脉虚数，虚主气阴亏耗，数示虚热。原文'克削过甚，津液元气俱伤'、'左脉虚数，右脉虚细，先天固属不足'，皆属气阴两虚之候。"}, {"name": "主脾虚胃弱", "desc": "右脉虚数，右候脾胃，虚为胃气少谷，数为虚热蒸腾。原文'质薄胃弱'、'脾弱胃强，恐转中满'，皆示脾胃虚弱、运化失职，故主脾虚胃弱。"}, {"name": "主营液内耗", "desc": "左脉虚数，左候肝，虚主营液亏耗，数为营热内扰。原文'营液内耗，肝阳内风震动'、'营热气偏'，皆因营阴不足、虚热内生，故主营液内耗。"}, {"name": "主气血俱虚", "desc": "右脉虚数，虚主气血不足，数为余热未清。原文'邪少虚多'、'气血俱虚，营卫不和'，热病后期邪去八九而气血未复，故主气血俱虚。"}], "n": {"主虚热": 4, "主气阴两虚": 1, "主脾虚胃弱": 2, "主营液内耗": 2, "主气血俱虚": 4}, "a": {"758": "主虚热", "794": "主营液内耗", "1396": "主营液内耗", "1842": "主气血俱虚", "11048": "主虚热", "11347": "主脾虚胃弱", "12829": "主气阴两虚", "13181": "主虚热", "13935": "主虚热", "15551": "主脾虚胃弱", "15880": "主气血俱虚", "24520": "主气血俱虚", "24521": "主气血俱虚"}, "t": 13, "np": 0}, "pc:六+细+虚": {"o": "六·细虚脉总主气血亏虚、元气不足之病机。虚为阳气衰微，细为阴血亏少，脉道不充，故其核心为气血两虚。然随程度与兼症不同，可细分：轻者主气血大虚，见脉虚细无力；重者主元气衰微，见虚细欲绝或欲脱；兼脾胃症者主脾胃虚损；正虚而邪恋者主正虚邪恋；妊娠见之则主胎元不固。诸类皆以虚为本，或纯虚，或虚中夹实，然总不离气血亏虚、元气不足之机。", "c": [{"name": "主气血大虚", "desc": "虚细脉为气血亏虚之典型脉象。虚为元气不足，细为阴血亏少，脉道不充。原文如霍乱吐泻后六脉虚细、产后痢肉脱骨存六脉虚细欲脱、疮疡脓水清稀六脉虚细无力等，皆因气血耗伤，脉道失充，故主气血大虚之证。"}, {"name": "主元气衰微", "desc": "虚细至极或欲绝、欲脱，示元气衰微将绝。如疟疾半载六脉虚细欲绝、孕妇泄泻六脉极虚细欲脱、产后痢六脉虚细欲脱，皆因久病耗伤，元气亏损已极，脉气衰微不能鼓动，故主元气衰微，预后多不良。"}, {"name": "主脾胃虚损", "desc": "虚细无力兼饮食减少、泄泻等，主脾胃虚损。如疮疡溃后六脉虚细无力、饮食减少，小儿手背发六脉虚细无力、大便日泻三四次，及五诊六脉虚细、饥不欲食、胃逆恶心，皆脾胃受损，气血生化无源，脉道不充所致。"}, {"name": "主正虚邪恋", "desc": "虚细脉亦见于正虚而邪气留恋之候。如产后头疼半年六脉虚细无力，为气血双亏、风寒乘虚侵入；瘟病后筋骨酸疼六脉虚细无力，为气血双亏、复伤肾水；湿热发黄误治后六脉虚细无力似有散意，为正虚胎元不固。皆正虚不能托邪，脉象虚细。"}, {"name": "主胎元不固", "desc": "妊娠病中见虚细脉，多主胎元不固。如孕妇泄泻六脉极虚细欲脱，为气血虚极、胎失所养；妊娠黄病误用寒利，六脉虚细无力似有散意，为气血不足、胎元欲散。虚细示气血亏虚，胎元失养，故主胎元不固。"}], "n": {"主气血大虚": 5, "主元气衰微": 3, "主脾胃虚损": 1, "主正虚邪恋": 1, "主胎元不固": 2}, "a": {"12131": "主元气衰微", "12177": "主元气衰微", "12204": "主胎元不固", "12210": "主元气衰微", "12226": "主气血大虚", "12227": "主气血大虚", "12244": "主气血大虚", "12253": "主正虚邪恋", "12263": "主气血大虚", "12274": "主胎元不固", "16755": "主脾胃虚损", "16861": "主气血大虚"}, "t": 12, "np": 0}, "pe:寸+数": {"o": "寸·数脉总以主热为纲，因寸候上焦，故热多偏于心肺、脾胃、胸膈。然具体病机须结合兼脉、按力及分部合参：数而有力多主实热，数而细弱多主阴虚火旺，数而兼滑主痰热，数而兼弦主肝郁化火，左寸独数主心火亢盛。又有寒热错杂如胃寒肠热、虚中夹实如尺沉细而寸关数者。诸类之间，实热、痰热、肝火、心火皆属阳热有余，可相互转化；阴虚火旺、虚中夹实属虚实夹杂，多由热盛伤阴或素体亏虚所致。总不离“数主热”之基本，而兼脉定其虚实脏腑。", "c": [{"name": "主实热", "desc": "寸数脉最直接主实热，数主热，寸候上焦。原文如“两寸脉数，心火烁金”“寸关俱数，舌苔黄燥”等，皆示热邪亢盛于上焦心肺、脾胃，脉数有力，症见发热、口渴、烦躁、苔黄。"}, {"name": "主阴虚火旺", "desc": "寸数而兼细、兼弱或尺部沉细，主阴液亏虚、虚火内生。如“左寸细数”主心血虚火旺，“右寸数大”主肺燥液干，“两尺沉数”主肾水燥竭，皆因阴不制阳，虚火上炎而脉数。"}, {"name": "主痰热", "desc": "寸数兼滑，滑主痰、数主热，主痰热壅阻上焦。原文“两寸关脉滑数”主痰热食积，“右寸关皆数”主痰湿郁热，症见咳嗽痰红、胸膈痞满、恶心食少，皆痰热内蕴之象。"}, {"name": "主肝郁化火", "desc": "寸数兼弦，弦主肝郁气逆，数主热。如“左寸关数”主肝木乘土、郁而化热，“左关脉数”主肝胆之热，症见抑郁不舒、食入即呕、口苦，皆肝郁化火、气逆上冲所致。"}, {"name": "主心火亢盛", "desc": "左寸独数或搏数，左寸候心，数主火。原文“左寸独锐，心经有火”致吐血，“左寸关搏数，心肝之火极炽”致下消，皆心火亢盛、迫血妄行或灼津为患，脉数而搏指。"}, {"name": "主胃寒肠热", "desc": "两寸皆数而关弦无力、尺洪滑，寸数主上焦热，关弦无力主脾胃虚寒，尺洪滑主下焦湿热。原文“胃寒肠热之证”即此，症见大便燥结、肠风脏毒，热在大肠而寒在脾胃，脉象寒热并见。"}, {"name": "主虚中夹实", "desc": "寸关数而尺沉细或脉数按之不足，主上焦有热、下元虚寒，或气阴两虚兼痰热。如“两寸关滑数，两尺沉细”主虚中夹痰饮，“脉数按之不鼓”主寒盛格阳，皆虚实夹杂之候。"}, {"name": "阴阳离决", "desc": "寸数而脉上出鱼际为溢脉，阴不敛阳，阳失阴守，见半身汗出等，属阴阳不相维系之危候。"}, {"name": "心肾气虚", "desc": "两寸脉十数至一歇，虚大参伍不调，主心肾气虚、脉行无力，非实热风邪，可伴水气上泛。"}], "n": {"主实热": 18, "主阴虚火旺": 7, "主痰热": 1, "主肝郁化火": 2, "主心火亢盛": 6, "主胃寒肠热": 4, "主虚中夹实": 4, "阴阳离决": 1, "心肾气虚": 1}, "a": {"308": "主心火亢盛", "683": "主实热", "2111": "主实热", "3071": "主实热", "3075": "主阴虚火旺", "3646": "主胃寒肠热", "3788": "主实热", "3917": "主阴虚火旺", "4240": "主胃寒肠热", "6006": "主实热", "6040": "主胃寒肠热", "6123": "主虚中夹实", "6248": "主实热", "6285": "主痰热", "6300": "主实热", "6334": "主胃寒肠热", "6418": "主虚中夹实", "6541": "主实热", "8545": "主肝郁化火", "8639": "阴阳离决", "10995": "主实热", "11524": "主虚中夹实", "11688": "主阴虚火旺", "12751": "主肝郁化火", "13638": "主心火亢盛", "13689": "主心火亢盛", "14753": "主心火亢盛", "14818": "主心火亢盛", "14983": "主阴虚火旺", "15542": "主阴虚火旺", "16153": "心肾气虚", "16254": "主虚中夹实", "16555": "主阴虚火旺", "21801": "主实热", "21803": "主实热", "21807": "主实热", "23815": "主实热", "24658": "主实热", "24660": "主实热", "24738": "主心火亢盛", "24780": "主实热", "24814": "主实热", "24930": "主阴虚火旺", "25103": "主实热"}, "t": 44, "np": 0}, "pe:左+虚": {"o": "左虚脉总以正虚为本，主气血阴阳亏耗，尤以阴血不足为核心。其虚而无力、细、芤者，主气血亏虚；虚馁、尺弱如绵者，主阴精亏虚；虚而弦劲者，主虚风内动；虚大、虚数、弦数上溢者，主虚火浮越；虚而兼弦、滑、涩、滞者，主虚实夹杂；左弦右濡者，主脾虚木乘。诸类之间，虚为共同基础，或兼风、兼火、兼痰、兼滞，然皆不离正虚之本质。左脉候肝心，故病机多涉肝阴血虚、心气不足，旁及脾肾。", "c": [{"name": "主气血亏虚", "desc": "左脉虚而无力、细、芤、小等，为气血不足、脉道不充之征。如左脉细按之空虚、左脉虚芤、脉虚无力，皆主血少气弱，营阴亏耗，常见于失血、崩漏、产后、八脉空虚等证。"}, {"name": "主阴精亏虚", "desc": "左脉虚馁、尺按之如绵、虚细而数，为肾阴亏虚、精血不足之象。原文见肾脉虚馁、五液不承、尺中细弱，主肾精不固、阴亏液耗，可见腰酸脊痛、口干喉燥、骨疽等。"}, {"name": "主虚实夹杂", "desc": "左脉虚而兼弦、滑、涩、滞等，为虚中夹实之候。如左脉弦虚主肝郁脾虚，左脉虚滞主气虚宿滞，左脉芤涩主营虚络滞，皆示正虚而兼气滞、痰瘀、积滞等实邪。"}, {"name": "主脾虚木乘", "desc": "左脉弦虚、右脉细濡，为脾土虚弱、肝木偏横之象。原文见左脉弦劲、右脉细濡，主操劳郁怒、肝木克脾犯胃，可见肩臂酸痛、嘈杂自汗、食入胀闷等。"}], "n": {"主气血亏虚": 20, "主阴精亏虚": 2, "主虚实夹杂": 4, "主脾虚木乘": 2}, "a": {"967": "主阴精亏虚", "990": "主气血亏虚", "1653": "主气血亏虚", "1742": "主气血亏虚", "3622": "主气血亏虚", "4231": "主气血亏虚", "6061": "主气血亏虚", "6097": "主气血亏虚", "6182": "主气血亏虚", "6278": "主气血亏虚", "6355": "主气血亏虚", "6391": "主气血亏虚", "6477": "主气血亏虚", "11010": "主脾虚木乘", "13277": "主虚实夹杂", "13883": "主虚实夹杂", "14057": "主气血亏虚", "15157": "主脾虚木乘", "15612": "主气血亏虚", "15816": "主阴精亏虚", "15938": "主气血亏虚", "16029": "主气血亏虚", "16033": "主虚实夹杂", "16528": "主气血亏虚", "20274": "主气血亏虚", "20608": "主虚实夹杂", "21801": "主气血亏虚", "24801": "主气血亏虚"}, "t": 28, "np": 0}, "c:弦+滑+虚+软": {"o": "虚弦软滑脉总属虚实夹杂之候，以正虚为本、痰阻气壅为标。虚软主体气素亏、脾肾不足，弦滑主痰饮内停、肝郁气滞或风阳内动。五段所主，或脾虚痰饮，或肾虚痰热，或痰凝气滞，或阴亏风阳挟痰，皆不离正虚与痰阻两端。其关系为：虚软定其本虚之脏（脾、肾、阴血），弦滑定其标实之邪（痰、火、风阳、气滞），二者相合，故见虚实夹杂、上盛下虚之象。总以扶正祛邪、标本兼顾为治。", "c": [{"name": "主脾虚", "desc": "虚软为脾脏受戕、中气不足，弦滑为肝火痰饮动扰。原文见嘈杂便溏、肠鸣少纳、舌淡无液，皆脾虚失运之征，故虚弦软滑主脾虚为本，痰饮为标。"}, {"name": "主痰凝气滞", "desc": "弦软为肝郁气滞，虚滑主痰凝，气逆面青、胸次坚硬如柈皆痰气壅塞之象。原文断为气滞痰凝，非热入血室，故脉主痰凝气滞、壅阻气机。"}, {"name": "主阴亏风阳", "desc": "软虚为阴血亏虚，滑为痰凝，弦为风阳内动。原文见头痛神疲、形瘦内烦、络胀少眠，乃阴亏水不涵木、风阳内炽、气郁痰凝，故脉主阴亏风阳挟痰。"}, {"name": "主虚实夹杂", "desc": "虚软主体气素亏、阳气不足，弦滑主痰阻清阳、气机壅塞。原文脉鼓指无力，提示痰热内阻而正气已伤，总属正虚为本、痰阻气壅为标之虚实夹杂候。"}], "n": {"主脾虚": 1, "主痰凝气滞": 1, "主阴亏风阳": 1, "主虚实夹杂": 2}, "a": {"4258": "主脾虚", "13249": "主虚实夹杂", "13355": "主痰凝气滞", "13450": "主阴亏风阳", "13856": "主虚实夹杂"}, "t": 5, "np": 0}, "c:细+浮+弱+缓": {"o": "浮细缓弱脉总属虚象，以血衰为核心，兼见虚风外扰与下焦亏虚。浮缓无力非表实，乃气血不足、卫外不固而虚风乘袭；细弱按之无力为阴血衰少、脉道不充；尺脉尤甚则下焦肾肝精血亏虚。三者相互关联：血衰为本，虚风为标，下焦亏虚为血衰之根。原文两段均断“病属血衰”，以四物汤加味取效，证明此脉所主以血虚失养为主，虚风与下焦亏虚皆由血衰派生，故治疗当以养血为本，兼顾熄风与补益下焦。", "c": [{"name": "主血衰", "desc": "脉浮细缓弱，按之无力，细弱为阴血不足，缓弱为脉道不充，尺脉尤甚则下焦精血亏虚。原文断“病属血衰”，年逾五十，血不荣筋则膝挛痛，夜甚于昼，小腹作痛，皆血虚失养之征。"}], "n": {"主血衰": 2}, "a": {"3934": "主血衰", "15263": "主血衰"}, "t": 2, "np": 0}, "c:数+大+虚+小": {"o": "数大虚小脉包括数大与虚小两种脉象，总起来主邪热与正虚两类病机。数大脉主邪热亢盛，虚小脉主正气不足。在病程中，脉由数大转为虚小无力，反映邪热虽减而正气亦虚，形成邪减正虚之候。原文强调此脉象变化为转危之兆，防神糊痉厥等变，提示正虚易致风动神浮。三类病机相互关联：邪热盛可耗伤正气，正虚又可致邪陷，故临证需动态观察脉象变化，以判邪正消长。", "c": [{"name": "主邪热", "desc": "脉数大，数主热，大主邪盛，为邪热亢盛之象。原文述服药前脉数大，伴脘痛、舌霉、唇焦等症，皆邪热内盛之征，故数大脉主邪热炽盛。"}], "n": {"主邪热": 2}, "a": {"13512": "主邪热", "14622": "主邪热"}, "t": 2, "np": 0}, "pc:左+数+弦+细+濡": {"o": "左·数弦细濡脉总起来主肝郁化火、阴血亏虚、脾虚有热、痰湿内蕴。左脉弦细，弦主肝郁，细主阴伤，因情怀抑郁，五志化火，木火刑金，血液暗耗；右脉濡数，濡主脾虚湿困，数主有热，为脾虚有热、痰湿内蕴。四类病机相互关联：肝郁化火是始动因素，火盛伤阴致阴血亏虚；木火刑金，肺失清肃则咳嗽气逆；肝病及脾，脾虚失运则痰湿内生，湿郁化热。脉象整体反映木火炎威无制而中土尚有生化之机，故治疗需养阴血清肝火、培中土生肺金，并怡情悦性。", "c": [{"name": "主肝郁化火", "desc": "左脉弦细，弦主肝郁气滞，细主阴血不足；情怀抑郁，五志化火，木火炎威无制，故脉见弦细。原文'左弦细为肝郁阴伤'，'木火炎威无制'，说明肝郁化火、阴血暗耗是核心病机。"}], "n": {"主肝郁化火": 1}, "a": {"317": "主肝郁化火"}, "t": 1, "np": 0}, "c:数+弦+小+促": {"o": "小弦数促脉总属肝阳化风、火郁阳亢之候。弦为肝风，小为阴伤，数促为火郁，合而示肝阳挟内风上扰，木火戕胃，阳越汗出。其病机以肝风内动为核心，阳亢火郁为关键，阳越汗出为变，暴厥瘈痉为极。四类相互关联：肝风内动则阳亢火郁，火郁阳亢则阳越汗出，阳升无制则暴厥瘈痉。总因操持怫郁，肝阳偏亢，逢春深阳升而加剧，故治以柔缓熄风和阳。", "c": [{"name": "主肝风内动", "desc": "脉弦为肝风之象，原文谓“弦为肝风”，且“厥阴脉小弦数促”，结合“肝阳挟持内风，直上巅顶”，故主肝风内动，症见头痛、惊惕肉𥆧等。"}], "n": {"主肝风内动": 1}, "a": {"810": "主肝风内动"}, "t": 1, "np": 0}, "c:弦+细+沉+促": {"o": "沉细弦促脉总起来主瘀血内阻、里虚、气滞与郁热。沉细主里虚，提示久痢正虚；弦主痛主瘀，促为气滞血瘀、郁而化热。四类病机相互关联：久痢正虚，气血不足，脉道不充则沉细；气虚推动无力，或情志不遂，则气滞血瘀；瘀血内停，气机不畅，郁而化热，故脉促。原文以瘀血痢为例，因饱食疾走、大怒不泄、补塞太过等致瘀血内停，脉象反映正虚与瘀热互结的复杂病机。临床见沉细弦促脉，当考虑虚实夹杂，以瘀血为核心，兼有里虚、气滞、郁热，治疗需活血化瘀，兼顾扶正行气清热。", "c": [{"name": "主瘀血内阻", "desc": "脉弦主痛主瘀，促为气滞血瘀、郁而化热。原文载痢久不愈，下紫黑血丝，丹溪断为瘀血痢，因饱食疾走、大怒不泄、补塞太过等致瘀血内停，脉沉细弦促反映瘀血内阻、气血不畅。"}], "n": {"主瘀血内阻": 1}, "a": {"3487": "主瘀血内阻"}, "t": 1, "np": 0}, "pc:左+数+弦+缓+和": {"o": "左·数弦缓和脉总起来主真阴不足、肝木偏亢及邪减向愈三类病机。其核心在于真阴亏虚，脉道不充则左脉细小无神；阴不涵木则肝气偏亢，关部带弦，进而肝木犯土。同时，右脉弦数转为缓和，提示邪气渐退、正气来复，属佳兆。三类病机相互关联：真阴不足为根本，肝木偏亢为继发，邪减向愈为转归，共同反映正虚邪恋、肝脾不和的复杂局面。", "c": [{"name": "主真阴不足", "desc": "左脉细小、按之无神，为真阴亏虚之象。原文指出‘细小无神又主乎真阴不足’，因阴血亏少，脉道不充，故脉体细小而无力，反映肾阴或肝阴亏虚的本质。"}], "n": {"主真阴不足": 1}, "a": {"9093": "主真阴不足"}, "t": 1, "np": 0}, "pc:右+数+大+微+缓": {"o": "右·数大微缓脉总属内伤不足、虚中夹实之候。其脉见于右手气口，与左人迎相对，气口大于人迎即内伤饮食劳役之征。数大急者，谷气壅盛、积滞化热，或虚火内扰；微缓者，胃气未绝，尚能抗邪。三类病机相互关联：内伤饮食为根本，积滞化热为标象，虚中夹实为整体格局。故其主病以脾胃内伤为核心，热壅与虚实夹杂为兼夹，总不离右手主里、气口候内伤之旨。", "c": [{"name": "主内伤饮食", "desc": "右寸气口脉大而数、急大，为饮食不节、劳役所伤之不足证。原文以气口大于人迎为内伤，右脉主里，数大急迫反映胃中积滞、谷气壅盛，故主内伤饮食。"}], "n": {"主内伤饮食": 1}, "a": {"19322": "主内伤饮食"}, "t": 1, "np": 0}, "pc:关+数+大+微+缓": {"o": "关·数大微缓脉总起来主内外伤之辨，以人迎、气口分左右。其病机不外两端：一为外感风寒，属有余之证，邪客肌表，正气抗邪，脉见数大微缓，多见于左手人迎；二为内伤饮食及劳役不节，属不足之病，脾胃受损，运化失常，脉亦见数大微缓，多见于右手气口。三类之间以“正虚邪滞”为共同基础：外感为客邪外来，内伤为脾胃自病，然脉象皆可因正气奋起或虚而兼滞而呈现数大微缓之象。临证当结合左右人迎气口之大小对比，辨其外感内伤之所属。", "c": [{"name": "主外感风寒", "desc": "原文以人迎脉辨外伤，谓外感风寒为有余之证，脉见于左手。外感寒邪则左寸人迎脉浮紧，按之洪大；外感风邪则人迎脉缓而大。数大微缓之象可因外邪客表、正气奋起抗邪而见，故主外感风寒之病机。"}], "n": {"主外感风寒": 1}, "a": {"19322": "主外感风寒"}, "t": 1, "np": 0}, "c:数+沉+浮+濡": {"o": "浮濡沉数脉总起来主湿热合邪、表里俱病，尤以湿热浸淫筋脉所致痿软为典型。其脉象由濡、数、浮、沉四要素复合而成：濡主湿，数主热，浮主表，沉主里，故浮濡沉数并见，既揭示湿与热合，又表明表里皆热。三分类中，‘主湿热’为病性总纲，‘主表里俱热’为病位分布，‘主湿热痿软’为具体病证，三者相互关联，共同构成湿热痿软的脉诊提纲。", "c": [{"name": "主湿热", "desc": "濡脉主湿，数脉主热，浮濡沉数并见，是湿与热合之象。原文明言‘濡主乎湿，数主乎热’，湿热交蒸，浸淫筋脉，故见痿软。此脉直接揭示湿热合邪为病之本质。"}], "n": {"主湿热": 1}, "a": {"24935": "主湿热"}, "t": 1, "np": 0}, "pc:六+细+沉+微+弱": {"o": "六·细沉微弱脉总起来主气虚、阳弱、寒凝三类病机。细沉微弱之脉，其形成机理在于气虚无力鼓动、阳弱不能温煦、寒凝阻滞气血，三者常相互影响：气虚日久可致阳弱，阳弱则寒凝内生，寒凝又加重气血不畅。原文以四君子汤治脾胃气虚为主，兼述胃寒气满、脾胃虚弱等证，涉及脉虚无力、六脉沉细、脉沉伏、六脉沉细微弱、脉涩、脉紧而涩等，诸脉皆不离气虚阳弱、寒凝气滞之本质。故临床见此脉象，当以补气健脾、温阳散寒为治，随证加减。", "c": [{"name": "主气虚", "desc": "原文列四君子汤治脾胃气虚、不思饮食，诸病气虚者以此为主，并涉及脉虚无力、六脉沉细等。细沉微弱之脉，因气虚无力鼓动血脉，故脉道不充而见细沉微弱，为气虚之典型脉象。"}], "n": {"主气虚": 1}, "a": {"27102": "主气虚"}, "t": 1, "np": 0}, "c:数+细+小": {"o": "细小数脉总以阴血亏虚、虚热内扰为基本病机。细主阴伤，小主脉道不充或气弱，数主有热，合而多示虚热，亦可兼实邪。诸类中，阴虚内热、气阴两虚、虚火动血、中虚伏热皆以虚为本、热为标，或偏阴亏，或偏气虚，或虚火灼络；痰热内闭、正虚邪恋则虚中挟实，或痰热弥漫，或水湿内停；妊娠一类为生理之变，血气羸弱之妇可见细小不数而隐有滑动。各证虽异，总不离“虚”与“热”两端，虚处多在阴血与气，热处多为虚火、伏热或郁热，兼夹则见痰、湿、瘀、邪。", "c": [{"name": "主阴虚内热", "desc": "细主阴血不足，小主脉道不充，数主有热。原文多谓细小数为阴液已伤、虚火内动，如溺血案肾阴不足、君相火下移小肠，齿龈痛案心肝虚火上炎，咳嗽案营阴不足、虚火灼肺，皆以阴亏为本、虚热为标。"}, {"name": "主痰热内闭", "desc": "细小而数兼右寸微浮而滑，细为阴伤，数为热，浮滑主痰。原文风温伏邪传入少阴，津灼为痰，痰热弥漫心包，灵机堵塞，肺炎叶枯，脉象示阴伤痰热内闭、化源告竭之危。"}, {"name": "主中虚伏热", "desc": "细小主中气亏虚、阴血不足，数主伏热内蕴。原文当脐胀痛按之则轻、得食则减，舌左黄右剥、质深红，脉细小而数，显系中虚作痛而非实积，虚中挟热，故曰中虚伏热使然。"}, {"name": "主虚火动血", "desc": "细小数为阴血不足、虚火内动，火逼血行或灼伤血络。原文溺血案君相之火下移小肠逼血下行，咳嗽案虚火灼肺、络伤痰红，齿龈痛案虚火上炎，皆细小兼数，主阴虚火旺、血不循经。"}, {"name": "主正虚邪恋", "desc": "细小主正虚，数主热，合示里虚有热、正虚邪恋。原文夏月暴冷伤中、泄痢耗液后，正虚水湿不化，通身浮肿，成冷下结，脉沉细小数，揭示病位在里、正气虚衰而兼热象，水湿内停。"}, {"name": "主妊娠", "desc": "妇人怀孕血留气聚、胞宫内实，脉多滑数倍常；然血气羸弱之妇亦见细小不数，但微弱中必有隐隐滑动之象，即阴搏阳别。原文辨胎孕脉数与劳损脉数相似，损脉多兼弦涩，胎脉必兼和滑，故细小而数亦可主妊娠。"}], "n": {"主阴虚内热": 1, "主痰热内闭": 1, "主中虚伏热": 2, "主虚火动血": 2, "主正虚邪恋": 2, "主妊娠": 1}, "a": {"82": "主痰热内闭", "449": "主虚火动血", "4593": "主正虚邪恋", "5901": "主中虚伏热", "8910": "主正虚邪恋", "10730": "主中虚伏热", "15678": "主虚火动血", "15921": "主阴虚内热", "23765": "主妊娠"}, "t": 9, "np": 0}, "pc:六+数+滑+洪": {"o": "六·数滑洪脉总属痰热壅盛之候。洪为热盛，数为邪炽，滑主痰饮，三者相合，示痰热互结、壅阻气机。所主病机以热盛为根本，痰壅为病理产物，痰热互结则成险候；若热毒痰瘀壅肺，则发为肺痈；若病久正伤而邪未退，则成正虚邪盛。各类之间以热为核心，痰为依附，热盛则痰聚，痰聚则热郁，互为因果，故脉象洪滑数并见，提示实热痰浊为患，治当清热化痰为主，兼顾扶正。", "c": [{"name": "主热盛", "desc": "洪脉为阳明热盛，数脉为邪热亢盛。原文多段见‘六脉洪滑而数’，并伴舌绛津枯、口渴烦躁、斑疹、肝阳火旺等，皆因热邪炽盛，故脉洪数相应。"}, {"name": "主痰壅", "desc": "滑脉主痰饮。原文载胸膈大痛、舌短痰嗽、咳吐臭脓血等，皆痰浊壅盛之征。痰随气升降，或化热成痈，脉滑即痰邪内盛之应。"}, {"name": "主痰热互结", "desc": "洪数滑并见，为痰与热互结。原文如温邪痰热炽盛、痰饮郁而化热、痰蓄胸中化热等，脉象示痰热胶结，壅阻气机，故见神识不清、肝风震动等险候。"}, {"name": "主正虚邪盛", "desc": "温病后期脉仍洪滑数，而见神志不清、肝风未平、舌燥绛，为正虚邪盛、痰热未清。脉象示邪热痰浊尚盛，故症险重，恐邪陷痉厥。"}], "n": {"主热盛": 2, "主痰壅": 2, "主痰热互结": 1, "主正虚邪盛": 1}, "a": {"1967": "主热盛", "1996": "主正虚邪盛", "1998": "主热盛", "3826": "主痰热互结", "26136": "主痰壅", "27103": "主痰壅"}, "t": 6, "np": 0}, "c:大+洪+芤": {"o": "洪大芤脉总起来主热盛伤津、气阴两虚之证。洪大主热邪炽盛，芤主阴血津液耗伤，二者并见，多因热盛于外而阴伤于内，或汗下误治耗伤津液，或产后血虚阳浮、心气不固所致。其病机类别之间相互关联：热盛为始动因素，热盛则伤津，津伤则气阴不足，甚则虚阳浮越、心气不固。故临床可见于热病痉厥、温毒发斑、暑温汗多、产后郁冒痉厥及死胎不下等证，治当清热生津、益气固脱、育阴潜阳，随证施治。", "c": [{"name": "主热盛", "desc": "洪大脉象主热邪炽盛，如第5158段热病瘛疭、痉厥神昏，脉洪大而芤，洪大为热盛；第5230段温毒发斑，右脉洪大芤甚，渴甚汗甚，皆热盛之征；第24380段暑温汗出烦渴而喘，脉洪大有力或洪大而芤，均示暑热炽盛。"}, {"name": "主津伤", "desc": "芤脉主阴血津液耗伤，洪大而芤并见为热盛伤津之象。如第5158段热病阴液亏耗；第5230段误汗下耗伤阴津，渴甚汗太甚；第24380段暑温汗出不止，热盛津伤、气阴不足，用白虎加人参汤。"}, {"name": "主气阴两虚", "desc": "洪大而芤亦主气阴不足、虚阳浮越。第24570段产后血虚阳浮，冒者汗者脉多洪大而芤，为血虚液短、阳孤不守；第24575段死胎不下，脉洪大而芤，大汗不止、精神恍惚欲脱，断为心气太虚、气浮血虚。"}, {"name": "主心气不固", "desc": "第24575段死胎不下，脉洪大而芤，兼大汗不止、精神恍惚欲脱，断为心气太虚不能固胎，洪大芤为气浮血虚、心气不固之象，故先固心气用救逆汤加人参，汗敛神宁而胎自下。"}], "n": {"主热盛": 1, "主津伤": 2, "主气阴两虚": 1, "主心气不固": 1}, "a": {"5158": "主热盛", "5230": "主津伤", "24380": "主气阴两虚", "24570": "主津伤", "24575": "主心气不固"}, "t": 5, "np": 0}, "pc:关+数+弦+大": {"o": "关·数弦大脉总起来主热盛邪实，兼有湿郁、火旺、阴伤之机。数主热，弦主湿郁或阳亢，大示邪盛，合而观之，其病机核心为热邪壅盛，但所在脏腑与兼挟不同。第一类湿热壅盛，偏于脾经伏热，湿邪下陷；第二类肝经火旺，偏于下焦肝肾火热内郁；第三类心肝阳扰，偏于上焦心肝火旺，阴亏复感暑邪；第四类阴虚火旺，偏于虚火内扰，肺肾阴伤。四类之间，前两类以实热为主，后两类兼有虚象，但总不离热盛邪实、弦大数之脉象特征。", "c": [{"name": "主湿热壅盛", "desc": "脉弦数大，弦主湿郁，数主热，大示邪盛。原文见热胜则肿、火甚则痛，午后发热、鼻准色赤、咽痛舌红，显系脾经伏热，湿邪下陷，湿热壅盛于中焦。"}, {"name": "主肝经火旺", "desc": "关尺弦大且数，关尺候肝肾，弦大为肝阳亢盛，数为热象，提示下焦肝肾火旺。原文虽未诊得实际脉象，但据证推脉，可知肝经火热内郁。"}, {"name": "主心肝阳扰", "desc": "脉数而左寸关兼弦大，数主热，弦大为心肝阳扰。原文述过扰心阳、兼伤谋虑，阴亏火旺，复吸暑邪，故发热纳阻、溲短便溏、气逆嗽痰、咽疼肿。"}, {"name": "主阴虚火旺", "desc": "脉虚弦软数或左寸关弦大以数，皆阴虚劳怯、咳嗽失血之脉。虚弦软数乃虚火内扰、肺肾阴伤；弦大以数，心肝火旺而阴不制，故见劳嗽失血。"}], "n": {"主湿热壅盛": 1, "主肝经火旺": 1, "主心肝阳扰": 1, "主阴虚火旺": 1}, "a": {"4680": "主湿热壅盛", "5959": "主肝经火旺", "13131": "主心肝阳扰", "26892": "主阴虚火旺"}, "t": 4, "np": 0}, "pc:右+数+滑+和": {"o": "右·数滑和脉总起来主痰热、燥热、气液亏虚及肝热内炽。其核心病机为肺胃痰热与燥热留恋，兼气液亏耗、肝热内炽。右脉候肺胃，滑数较和示痰热渐化而未尽，燥热未澈；气液素亏则脉虽和而数滑，形神衰弱；左脉弦数不靖反映肝热内炽，木火易炽。诸类之间，痰热、燥热为标，气液亏虚为本，肝热内炽为兼夹。脉象‘较和’提示邪势渐退，但余焰未清，故治疗需清余燥、化痰热，兼顾气液，不可早进滋阴。", "c": [{"name": "主痰热", "desc": "右脉滑数较和，滑主痰，数主热，右候肺胃，故主肺胃痰热。原文多次言‘痰热渐化’‘燥痰未澈’，并引‘火灼津液为痰’，说明滑数脉反映痰热内蕴，病位在肺胃。"}], "n": {"主痰热": 3}, "a": {"65": "主痰热", "66": "主痰热", "67": "主痰热"}, "t": 3, "np": 0}, "c:数+微+小": {"o": "小数微脉总起来主虚损夹杂之候，以阴血亏虚为本，虚火、邪热为标，或兼阳气衰微、阴寒内盛。其核心病机为真阴不足、虚火内动，可致虚火动血而见吐血，或肺胃阴伤而见咳呛咽燥；若脉兼滑数，则转为阳虚阴盛、虚阳不藏；若兼数急，则示正虚邪热夹杂。各类之间以虚损为共同基础，或偏于阴虚火旺，或偏于阳虚阴盛，或虚中夹实，反映了病机的复杂性与转化。", "c": [{"name": "主阴虚火旺", "desc": "脉小数微，数为虚热，小为阴亏，微为阳弱。原文'脉小微数，真阴不足'及'数主热，小主虚'，皆示阴液亏虚、虚火内动。阴不制阳则数，阴血不足则小，故主真阴不足、虚火内郁之候。"}, {"name": "主虚火动血", "desc": "吐血因劳怒即发，脉小数微呛。数主火，小主阴虚，火动于阴分，迫血妄行。劳则伤脾耗阴，怒则肝火上升，思虑劳心灼阴，血随气逆。脉数示火未熄，小示阴已亏，故主阴虚火旺、热迫血溢之吐血。"}], "n": {"主阴虚火旺": 1, "主虚火动血": 2}, "a": {"599": "主阴虚火旺", "5729": "主虚火动血", "17936": "主虚火动血"}, "t": 3, "np": 0}, "c:数+浮+小": {"o": "浮小数脉总起来主表邪留恋、风热犯肺、正虚邪恋、风火相搏及气阴两伤等病机。浮为邪在表或气虚外浮，数为热，小为邪郁或阴血不足。各段所主虽有偏重，但多围绕外邪与正虚交织：或表邪未尽而余热未清，或风热上攻肺胃，或正虚邪恋、风火相搏，或气阴两伤、虚热内扰。其共同特点是浮、数、小并见，提示病位偏表偏上，邪郁化热，兼有正气不足或阴分受损。临床当结合兼脉及症候，辨其邪正盛衰，分别施以疏解、清降、扶正祛邪等法。", "c": [{"name": "主表邪未尽", "desc": "浮脉主表，数主热，小示邪势已衰。原文见“脉浮小数，邪未尽彻”，进药后白㾦发出、热减而脉转浮小，说明表邪留恋肌表，余热未清，故浮小数并见，提示当继续疏解透邪。"}, {"name": "主风热犯肺", "desc": "浮为风，数为热，小为邪郁。原文“脉象浮小兼数”伴冒风咳嗽咽疼、吐血，断为“阳明胃土攸关”，风热犯肺、胃火上升，阳络伤则血外溢，故浮小数主风热上攻、肺胃热盛。"}, {"name": "邪伏于里", "desc": "脉小数不浮，数主热，小主邪郁，不浮示邪不在表。症见身热头胀、骨节疼，为时邪内伏，郁而化热，不能外达，法宜疏解里邪。"}], "n": {"主表邪未尽": 1, "主风热犯肺": 1, "邪伏于里": 1}, "a": {"15540": "邪伏于里", "15930": "主表邪未尽", "16046": "主风热犯肺"}, "t": 3, "np": 0}, "pc:右+弦+细+滑": {"o": "右·弦细滑脉总起来主肝郁血少、痰湿内滞及血虚夹痰之病机。弦细主肝郁血少，情志怫郁，阴血不足；滑主痰湿内滞，脾运不健，痰浊内生。二者相合，常见肝脾失调、痰湿内阻之证，如寒热交作、呕哕、遍身疼；若血虚与痰浊并见，则致神识迟钝、盗汗等。各类之间相互关联：肝郁血少可致脾运不健而生痰，痰湿内滞又可进一步耗伤阴血，形成虚实夹杂之局。临证需权衡虚实，疏肝养血与化痰祛湿并施。", "c": [{"name": "主肝郁血少", "desc": "弦细为肝郁血少之象，情志怫郁，肝气不舒，血亏脉道不充。原文见丧子哀恸、绝粒断浆，左脉弦细，正合肝郁血少之机。"}], "n": {"主肝郁血少": 2}, "a": {"6148": "主肝郁血少", "11278": "主肝郁血少"}, "t": 2, "np": 0}, "c:大+紧+迟": {"o": "迟紧大脉总起来主寒实内结、邪实壅盛之病机。迟主寒，紧主寒凝劲急，大示邪实壅盛，三脉相合，多属寒邪为患而正气未虚。其具体所主，或为寒邪外束、肺气闭郁（如案2寒客会厌致卒然无音），或为寒实内结心下（如“紧大而迟者，必心下坚”），或为阳中有阴、寒实可下之证（如“脉大而紧者，阳中有阴，可下之”）。各类之间，总以寒邪凝滞、实邪壅盛为共同基础：寒凝则脉迟紧，邪实则脉大；寒凝可致气机闭郁，实邪可结于胸膈心下，甚则形成可下之证。故临床见此脉，当辨寒实之部位与轻重，以温散、开提或攻下为治。", "c": [{"name": "主寒凝", "desc": "脉迟紧大，迟主寒，紧主寒凝，大示邪实壅盛。如案2寒邪客于会厌，卒然无音，为寒邪外束、肺气闭郁；又如原文“紧大而迟者，必心下坚”，寒实内结心下，脉气劲急。故主寒邪凝滞、阳气被遏之病机。"}], "n": {"主寒凝": 2}, "a": {"11816": "主寒凝", "25321": "主寒凝"}, "t": 2, "np": 0}, "c:数+促+坚": {"o": "坚数促脉总起来主水亏热升、虚火内迫之证。左脉候肝肾，坚为阴亏阳亢，数为热，促为热盛而气机急促，三者相合，示水不制火、龙相之火上炎。原文冬温咳嗽，水亏热升，热灼胃阴，秽浊上冲咽喉，故脉见坚数促。其病机核心为阴亏于下、热升于上，涉及肝肾龙相火炎与胃阴受伤两端，总属虚热内迫之候。", "c": [{"name": "主水亏热升", "desc": "脉左坚数促，左候肝肾，坚为阴亏阳亢，数为热，促为热盛气急。原文冬温咳嗽，水亏热升，龙相之火上炎，正合坚数促所示水不制火、虚热内迫之机。"}], "n": {"主水亏热升": 1}, "a": {"894": "主水亏热升"}, "t": 1, "np": 0}, "pc:左+数+弦+和": {"o": "左·数弦和脉总起来主肝郁化火、饮邪内停、脾虚湿胜及肺失宣降四类病机。其核心在于肝郁化火，弦为肝邪，数主郁热，左关弦数不和是肝郁化火之明征。肝郁则木失疏泄，影响肺金宣降，金郁则失清肃之令，故咳呕并作；木郁犯土，脾运失健，湿邪内胜，故右脉细濡涩而便溏。饮邪内停亦因气机郁滞，水饮不化，弦脉主饮。四类病机相互关联：肝郁化火为始动因素，进而影响肺、脾，形成肺失宣降、脾虚湿胜；饮邪内停则是气郁湿聚之果。总属内伤杂病，以肝郁为中心，涉及肺脾，虚实夹杂，郁热与湿饮并存。", "c": [{"name": "主肝郁化火", "desc": "左关弦数不和，弦为肝邪，数主郁热。原文谓木郁失疏泄之常，肝气郁结日久化火，故脉见弦数。此乃肝郁化火之病机，属内伤郁热范畴。"}], "n": {"主肝郁化火": 1}, "a": {"2017": "主肝郁化火"}, "t": 1, "np": 0}, "pc:六+大+洪+空": {"o": "六·大洪空脉总起来主虚阳外越、真寒假热、内虚寒盛之证。其脉象洪大而空，浮取无伦，沉取无根，是阳气浮散于外而内里虚寒的典型表现。原文所载身大热、口大渴、面赤娇红、四肢厥冷、舌黑滑胖等，皆属格阳戴阳、虚阳外越之候。洪大为空，非实热白虎证，乃内真寒外假热之象。三类病机相互关联：虚阳外越是病机核心，真寒假热是其外在表现，内虚寒盛是其内在本质，三者一体，共同揭示阳气浮散、阴寒内盛之病机。", "c": [{"name": "主虚阳外越", "desc": "脉洪大而空，浮取无伦，沉取无根，为阳气浮散于外、内里虚寒之象。原文见身大热、口渴、面赤娇红、四肢厥冷过肘膝，舌黑滑胖润，显系格阳戴阳，虚阳外越，故脉虽洪大而中空无根。"}], "n": {"主虚阳外越": 1}, "a": {"3345": "主虚阳外越"}, "t": 1, "np": 0}, "pc:右+数+细+软": {"o": "右·数细软脉总起来主虚火内扰、脾肾不足及三焦同病。其脉细软为虚，数为火象，合示阴液亏虚而虚火内生。虚火非上扰即下迫：上扰则耳鸣响闷，下迫则关门不固、梦泄；上热下热必及于中，致胃不能容、脾不能运，消化迟缓、大便不畅。右脉候脾肾，细软尤显虚象，故又主脾肾两虚，运化封藏失职。三类病机相互关联：虚火为标，脾肾虚为本，三焦同病为果，总属本虚标实、虚火弥漫之候。", "c": [{"name": "主虚火", "desc": "脉细软俱见数象，细软主虚，数主虚火。原文谓“虚火非上扰即下迫”，上扰则耳鸣响闷，下迫则关门不固、梦泄，示虚火充斥三焦，非实热可比。"}], "n": {"主虚火": 1}, "a": {"9127": "主虚火"}, "t": 1, "np": 0}, "pc:右+弦+滑+浮": {"o": "右寸关弦滑浮脉总起来主痰实于上、微兼客热，并常与下焦阴虚并见。弦滑主痰实，浮主客热，左关尺细软无神主阴虚于下。三类病机相互关联：痰实壅于上焦，客热犯于表或上焦，而阴虚于下则为本虚，形成上实下虚、虚实夹杂之候。原文强调攻补皆难偏任，故治疗需清化痰热兼滋下焦，浊药轻投。", "c": [{"name": "主痰实", "desc": "右寸关弦滑而浮，弦滑主痰实。原文以弦滑为痰实之征，结合痰嗽喘逆、便秘不眠，说明痰浊壅盛于上焦，气机不畅，故脉见弦滑。"}], "n": {"主痰实": 1}, "a": {"14475": "主痰实"}, "t": 1, "np": 0}, "c:弦+动+长": {"o": "弦长动脉在原文中特指“足厥阴肝痧”的脉象，总起来主肝经痧邪为患。其病机核心为邪扰肝经、血络受伤：弦为肝脉，长为气机壅滞，动为邪正交争，三者相合，既反映痧邪侵犯肝经，又提示血分受伤、气血扰动。与段落中其他痧脉（如芤而浮主肺痧、芤而数主心痧等）相比，弦长而动独应肝经，体现了以脉象形态和动态定位痧邪所犯脏腑的辨证思路。因此，弦长动脉所主病机可归纳为肝痧、血伤、邪扰三类，三者相互关联，共同指向肝经痧毒内蕴、气血失调的病理状态。", "c": [{"name": "主肝痧", "desc": "原文明确指出“脉弦长而动者，足厥阴肝痧也”，弦长而动为肝经痧邪所犯的典型脉象。弦为肝脉，长为气机不畅，动为邪正交争，故主肝痧。"}], "n": {"主肝痧": 1}, "a": {"18443": "主肝痧"}, "t": 1, "np": 0}, "c:大+缓+平": {"o": "大缓平脉以和柔从容、胃气存为平，然其变异则主脾土之病。总起来看，此脉所主病机以脾为中心：平脉示无病，实盈数主脾病邪实，坚锐弱散主脾死胃竭，鸟喙不及主中虚九窍壅塞。四类之间以胃气存亡为枢：胃气存则平，邪实则病，胃气竭则死，中虚则不及。故大缓一脉，平病生死皆可察，而总不离脾土之盛衰。", "c": [], "n": {}, "a": {"21531": "__np"}, "t": 1, "np": 1}, "pc:尺+细+沉+小": {"o": "尺部细沉小脉在《伤寒论》类原文中，主要出现在伤寒温病的预后判断中。其总病机为正气虚衰、无力抗邪，或邪气内陷、正不胜邪。具体而言：伤寒热盛时见沉小，为邪实正虚、邪陷于里，主凶；汗后见沉小，为汗出津伤、脉证相符，主吉；温病大热而脉细小难得，为阴液耗竭、正气败绝，主死。三类均围绕正虚与邪盛的力量对比，沉小之脉反映正气不能鼓动血脉以抗邪，故其预后取决于是否与病机相符：邪盛时见之则危，汗后见之则安。总以正虚邪陷为核心，兼及汗后正伤与温病正败。", "c": [{"name": "主正虚邪陷", "desc": "伤寒热盛时脉沉小，为邪盛而正气不能外抗，邪气内陷，故主死。原文'伤寒热盛，脉浮大者生，沉小者死'，沉小示正虚无力托邪，病势危重。"}], "n": {"主正虚邪陷": 1}, "a": {"21824": "主正虚邪陷"}, "t": 1, "np": 0}, "c:微+涩+疾": {"o": "微涩疾脉总起来主癫疾，其病机以心气不足、血涩不荣为本，风邪急搏、热盛动风为标，兼及肾虚骨癫与湿浊内蕴。微涩主心气亏虚、血行涩滞，疾紧主风邪急搏、热盛动风，诸脉象可单独或相兼出现，反映癫疾虚实夹杂、多脏受累的特点。原文列五癫诊脉，以微涩为心癫之脉，紧疾为脾癫之脉，肾急甚为骨癫，又湿癫因湿浊内蕴，故微涩疾脉所主病机涵盖心、脾、肾及湿浊为患，总以正虚邪扰、神机失用为要。", "c": [{"name": "主心气不足", "desc": "原文谓“心脉微涩为癫疾”，微涩之脉主心气不足。心主血脉，心气亏虚则血行涩滞，脉道不充，故见微涩。心气不足则神失所养，发为癫疾，故微涩脉主心气不足、血涩不荣之病机。"}], "n": {"主心气不足": 1}, "a": {"22103": "主心气不足"}, "t": 1, "np": 0}, "c:微+缓+和": {"o": "微和缓脉总以“和缓”为胃气之象，其核心病机在于胃气的盛衰与邪正的进退。和缓脉本身并非独立病脉，而是判断胃气存亡及疾病预后的关键指征。若脉由和缓转为弦急，为邪气渐进、胃气受遏，病势加重；若由弦急转为和缓，或初急后缓，为胃气来复，病势向愈；若初缓后急，则胃气衰去，病趋危重。四时平脉微兼弦、钩、毛、石而和缓，为有胃气之常；若脉无和缓而真脏脉独见，则胃气竭绝，主死。故各类病机均围绕胃气之有无、来去、盛衰展开，和缓脉之变化实为观察邪正进退与胃气存亡的窗口，对判断疾病轻重及生死预后具有重要价值。", "c": [{"name": "主邪进病甚", "desc": "脉由和缓转为弦急，提示邪气渐进，胃气受遏。原文“今日尚和缓，明日更弦急，知邪气之愈进”，邪愈进则病愈甚，故和缓脉之消失反映邪盛病进。"}], "n": {"主邪进病甚": 1}, "a": {"22805": "主邪进病甚"}, "t": 1, "np": 0}, "c:数+洪+散": {"o": "洪数散脉在疮疽辨证中总属邪热壅盛而正气涣散之候。洪数主热毒炽盛，粗散主气血耗散，二者相合，形成邪实正虚的复杂病机。原文以“脓溃后烦疼不除，脉洪数粗散者，为热毒未清而气血已散”为据，说明此脉既反映热毒未清之邪实，又揭示气血已散之正虚，故属难痊之象。三类病机相互关联：热毒壅盛为病之因，气血耗散为病之果，邪实正虚为整体格局。与微涩迟缓脉对比，洪数粗散主邪盛正散，预后较差，体现了脉象在判断疮疽善恶顺逆中的关键作用。", "c": [{"name": "主热毒壅盛", "desc": "脉洪数粗散，洪为热盛，数为热急，粗散示热毒炽张。原文“脓溃后烦疼不除，脉洪数粗散者，为热毒未清”，说明疮疽溃后脉仍洪数粗散，是热毒壅盛未解之象。"}], "n": {"主热毒壅盛": 1}, "a": {"23914": "主热毒壅盛"}, "t": 1, "np": 0}, "pc:六+虚+实": {"o": "虚实脉总以虚象为主，主正气亏虚，然虚中每夹邪实，或为邪陷欲脱，或为虚中夹实，或为正虚风动。其脉象多微细、虚软无力，甚则无伦次如虾游，反映气血不足、元气衰败。然虚脉亦可见假实之象，如瘀血内阻致脉细数无力，误补后脉虚变实；或虚而病形实，当辨虚实真假。各类之间，正虚为本，邪陷、夹实、风动为标，总属虚实夹杂之候，诊脉当参合病形，以决死生预后。", "c": [{"name": "主正气虚衰", "desc": "脉微细、虚软无力，为气血大虚、元气衰败之象。原文如“六脉微细之极”示气血大虚，“六脉细数无力”似产后气血双亏，“六脉弦续而虚软无力”示气血不足、脉络失养。虚脉主正虚，因气血不足，脉道不充，故按之无力。"}, {"name": "主邪陷欲脱", "desc": "脉微数无伦次、如虾游，为正气内亏、邪气内陷、胃气衰败之危候。原文“六脉俱微数，极无伦次，又若虾游状”见于瘟疫经水适来，里虚邪陷，正气欲脱；又“动气一止”为正气内亏、气血不能守卫，邪气内陷之机。"}, {"name": "主虚中夹实", "desc": "脉虚而病形实，或脉由虚变实，为虚中夹实、瘀血内阻之假虚象。原文“六脉微细之极”而心脾高肿作痛、呕吐不止，乃虚中夹实；又“六脉细数无力”误补后“脉虚变实”，悟为恶露未尽、瘀血内阻，瘀血得补而壅滞化热。"}, {"name": "主正虚风动", "desc": "脉弦续而虚软无力，为气血不足、脉络失养，风邪内动之象。原文“六脉弦，续而虚软无力”示正虚而风邪内动，虽未倒仆，其中风晕厥之候可指日而决，强调脉之虚软处即正虚之所在，当补脾肺肾以预防。"}], "n": {"主正气虚衰": 1, "主邪陷欲脱": 2, "主虚中夹实": 3, "主正虚风动": 1}, "a": {"2961": "主邪陷欲脱", "3384": "主邪陷欲脱", "4056": "主虚中夹实", "12265": "主虚中夹实", "12266": "主虚中夹实", "18360": "主正虚风动", "21825": "主正气虚衰"}, "t": 7, "np": 0}, "pc:六+弱+软": {"o": "弱软脉总主虚证，以气虚、脾虚、肾虚及气血大虚为核心。其脉象软弱少力，软主虚，弱主气血不足，故凡见六脉软弱，多提示正气亏虚。从所收段落看，或为脾肺气虚之咳呛脾泄，或为脾虚不统血之痔血便频，或为肾元亏败之牙疳重症，或为气血大虚之脉如游丝。各类之间相互关联：气虚可累及脾肺，脾虚日久可致气血两虚，肾元亏败则根本动摇，气血大虚则脉道不充。总属虚损之候，病位涉及脾、肺、肾，病性以气虚、血亏、阳衰为主，治当温补培元、健脾益气、养血填精，随证施治。", "c": [{"name": "主脾虚不统血", "desc": "脉六部皆软弱无力，主脾虚不能统血。原文载痔血、便频、肌肉脱，因过服凉血药损伤脾阳，脾失统摄，血不循经而下溢；脾虚运化失职，故食入即行。脉软无力正合脾虚失运、气血不摄之候。"}, {"name": "主肾元亏败", "desc": "六脉软弱，示正气虚衰、肾元亏败。原文见牙疳碎烂色紫暗、舌滑带黑、下门齿脱落，皆肾经虚火上浮、骨中湿毒内蕴之象。脉软弱与虚症相符，故断为虚症之极重险者，治宜桂附导火归原。"}, {"name": "主气血大虚", "desc": "脉软弱如游丝，为气血大虚、正气衰惫之象。软主虚，弱主不足，细如游丝则阴血亏甚、脉道不充。原文见于梦泄神虚之后，说明久泄精亏、气血两伤，故脉见软弱如游丝，主气血大虚。"}], "n": {"主脾虚不统血": 3, "主肾元亏败": 1, "主气血大虚": 2}, "a": {"2220": "主脾虚不统血", "2253": "主气血大虚", "6048": "主脾虚不统血", "6342": "主脾虚不统血", "14968": "主肾元亏败", "18234": "主气血大虚"}, "t": 6, "np": 0}, "pc:右+滑+涩": {"o": "右·滑涩脉总起来主虚实夹杂之证，以痰（湿、火）与血瘀、血少并见为核心。滑脉主痰积、痰湿、痰火及阳盛火动，属邪实一面；涩脉主血瘀、血少阴亏及脏虚，属正虚或血行不畅一面。二者相合，常见痰瘀互结、湿热壅盛、燥火内动而兼营血内枯或下元虚惫。各段所论，或偏痰积血瘀（如），或偏痰火血少（如），或示虚阳外浮而根本不足（如），然总不离痰、瘀、虚、火相互交织之病机。", "c": [{"name": "主痰积", "desc": "右滑脉主痰积、痰湿内盛。原文如“右滑主痰积”，“右滑为痰湿内盛”，“右滑主痰火内盛”，“滑为阳盛”。滑脉应指圆滑，为阳气有余、痰湿或痰火内聚之象，故右滑多主中上焦痰湿、痰火壅盛。"}, {"name": "主血少阴亏", "desc": "涩脉主血少、阴液亏耗。原文“营血内枯”“老年阴液已亏”，“血少藏聚，流而不行”。涩为血少之象，阴血不足则脉道不充、血流艰涩，故涩脉主营血内枯、阴液亏虚。"}, {"name": "主阳盛火动", "desc": "滑脉主阳盛、燥火易动。原文“燥火易动”，“滑为阳盛”“亢乃燥气乘复”。滑为阳气有余，阳盛则化火生燥，燥火内动，上扰清窍，致气逆胸痞、噎塞等症。"}, {"name": "主脏虚", "desc": "涩脉按之微弱，主五脏之虚。原文“举指而滑，按之而微”“按之沉小微弱短涩软濡，俱为脏虚”。滑为虚阳浮于外，涩为正气内衰，故脉见滑涩兼微，主脏气亏虚、根本不足。"}], "n": {"主痰积": 2, "主血少阴亏": 1, "主阳盛火动": 1, "主脏虚": 1}, "a": {"6118": "主痰积", "6413": "主痰积", "18537": "主血少阴亏", "18540": "主阳盛火动", "22693": "主脏虚"}, "t": 5, "np": 0}, "pc:六+虚+微": {"o": "虚微脉总主正气大虚，包括元气虚弱、气血大虚、气阴两虚及津液内亡。其脉象虚微，反映人体精气营血亏耗，脏腑功能衰退。各段所主虽有侧重：或为元气虚弱、心神虚损，或为气血大虚、虚寒夹饮，或为气阴两虚、暑伤脾胃，或为津液内亡、化源不足，但均以正虚为根本。虚微脉提示病机以虚为主，或兼夹他邪（如寒饮、暑湿、里热），但正虚始终是核心。临床见六脉虚微，当以补益为要，兼顾兼证。", "c": [{"name": "主气阴两虚", "desc": "六脉虚微为气阴两虚之象。暑月泄泻、小便赤、四肢疲困、自汗微热口渴，素羸瘠，此暑伤气阴、脾胃虚弱，非虚劳也。脉虚微揭示气阴耗伤，正虚不足。"}, {"name": "主气血大虚", "desc": "虚微为气血大虚。新产之后气逆如喘、痰多白腻、心悸汗出、耳鸣头晕，右寸关沉弦主里主饮。虚微示正虚，沉弦示寒饮内伏，病机属虚寒夹饮，气血大虚为本。"}, {"name": "主元气虚弱", "desc": "六脉虚微为元气虚弱、心神虚损之象。大病后谷消水去精散卫亡，脾失健运，津液不布，故便利枯渴。脉虚微主正气大虚，与饮食不思、心神虚损相应。"}, {"name": "主津液内亡", "desc": "伤寒小便不利，六脉虚微为内亡津液，化源不足。身热脉浮为热结膀胱，右脉洪数主阳明湿热，六脉沉数主里热便结。虚微示津液耗伤，化源亏乏。"}], "n": {"主气阴两虚": 1, "主气血大虚": 1, "主元气虚弱": 1, "主津液内亡": 1}, "a": {"2992": "主元气虚弱", "3439": "主气阴两虚", "8111": "主气血大虚", "25090": "主津液内亡"}, "t": 4, "np": 0}, "pc:两+数+濡": {"o": "两·数濡脉总以湿、热、虚三者交织为病机核心。濡主湿，数主热，合之则湿热内蕴，见于湿滞中焦、脾运失职之证；若数而无力，则又主元气虚馁、虚阳浮动，常见脾阳久虚、聚湿生痰。此外，濡数可主湿温病阴伤，因伏温熏蒸、阴液耗损；若兼滑数无力，则主痰热而气阴不足。四类病机相互关联：湿热内蕴可困阻脾阳，久则脾虚生痰；湿温阴伤与痰热气虚则多因热邪耗气伤阴所致。总不离湿、热、虚三端，而虚实夹杂为其要。", "c": [{"name": "主湿热", "desc": "濡主湿，数主热，合为湿热内蕴。如段两脉濡数，伴舌苔淡黄而白、便溏腹胀，为湿滞中焦、脾运失职之象，故脉濡数正应湿热挟土之机。"}, {"name": "主湿温阴伤", "desc": "濡数并见，可主湿温病阴液耗伤。段脉两尺濡数，伴肌热不退、口渴溲赤、尺肤热甚，为伏温熏蒸、阴分受损之征，故曰濡数主湿温阴伤。"}, {"name": "主脾虚湿痰", "desc": "濡数无力，濡主湿，数而无力为元气虚馁、虚阳浮动。段脾阳久虚，聚湿生痰，胃气失和，症见足浮痰多纳少，脉濡数无力正应脾虚湿痰、元气亏乏之机。"}], "n": {"主湿热": 1, "主湿温阴伤": 1, "主脾虚湿痰": 1}, "a": {"63": "主湿温阴伤", "9164": "主湿热", "17991": "主脾虚湿痰"}, "t": 3, "np": 0}, "c:小+促": {"o": "小促脉总起来主正虚邪郁、阳郁痹结之候。其脉形小主气弱阴伤，促主气结、热郁或虚中夹滞，合而示正气不足而邪气郁遏。所主病机大致四类：一为阳气痹结、清阳不升，见脘痛胀满、四肢不暖；二为气血两虚、营卫俱损而虚中夹滞，多见于疟久正伤；三为热盛阴伤或痰火内郁，数促主热、小主虚；四为伏邪在里、客气从热化，里热上逆而正已不足。四类之间，虚为本，郁、热、滞为标：或阳虚而痹结，或血虚而邪滞，或热盛而阴伤，或伏邪而正虚，总不离‘小’示正虚、‘促’示郁结与邪热。故小促脉非纯实纯虚之脉，而是虚中夹郁、正虚邪陷之象，临证须辨其郁结、热邪与虚损之孰轻孰重。", "c": [{"name": "主阳郁痹结", "desc": "小促脉主阳气痹结、清阳不升。原文见右脉小促，伴脘痛梗突、食减胀满、四肢不暖、便血，断为‘阳气痹结’‘清阳痹结’，久则阳微痹结，上下不行，有否卦之义。小主气弱，促主气结，阳气郁遏不通，故成痹结之候。"}, {"name": "主伏邪里热", "desc": "小促脉主伏邪在里、客气从热化。原文脉小促，舌黄、语塞、口渴、喘息、下利黑水，寒热不止，汗泄甚多，断为伏邪在里，里热肾气不纳，里气上逆。小为正气不足，促为邪热内迫，故主里热久伏、正虚邪陷之候。"}], "n": {"主阳郁痹结": 2, "主伏邪里热": 1}, "a": {"1154": "主阳郁痹结", "4510": "主阳郁痹结", "4653": "主伏邪里热"}, "t": 3, "np": 0}, "pc:左+滑+疾": {"o": "左·滑疾脉总起来以痰湿、热盛、气虚、阴亏为核心病机，常呈虚实夹杂。滑主痰湿、血多气少，疾主热盛急迫，故本脉可主痰湿化热、阳热亢盛；若滑疾无力，则主气虚痰湿；若与虚弦并见，则主阴亏痰湿。各段原文均围绕“滑主痰湿，疾主热盛”展开，兼见气虚、阴亏等虚象，说明本脉非单纯实热，而是痰湿与热相合，或虚实互见，病位涉及中焦、肺、肝肾，以湿痰酿热、气阴不足为要。", "c": [{"name": "主痰湿化热", "desc": "滑主痰湿，疾主热盛。原文如案9“右脉滑疾”示中焦湿痰化热，积饮酿热；案12826“滑疾为中虚湿痰不运”，均因痰湿内蕴，郁而化热，脉见滑疾。"}, {"name": "主气虚痰湿", "desc": "滑疾无力为气虚有痰。案12827“右脉滑疾无力”伴气虚有痰、脾虚生湿，因气不运痰，痰湿内停，脉虽滑疾而无力，反映本虚标实之机。"}, {"name": "主阴亏痰湿", "desc": "左脉虚弦、右脉滑疾，虚弦为心肝肾阴不足，滑疾为中虚湿痰不运。案12826示阴亏于下、痰湿阻于上，清窍失聪，脉象合为阴亏痰湿之病机。"}], "n": {"主痰湿化热": 1, "主气虚痰湿": 1, "主阴亏痰湿": 1}, "a": {"12508": "主痰湿化热", "12826": "主阴亏痰湿", "12827": "主气虚痰湿"}, "t": 3, "np": 0}, "pc:右+大+平": {"o": "右·大平脉总起来主邪气偏盛于右部所候之脏腑，以肺、胃为主，兼及肝木乘土。其病机主要有三类：一为肺经热壅，右脉洪大，热邪痹阻肺经；二为新邪引动伏饮，右脉平而左大，提示新感未深陷，伏饮内动；三为肝木犯土，右脉弦大不平，木旺土虚，胃失冲和。三类之间相互关联：肺热可致痹症，伏饮可因新邪而发，肝木乘土则影响胃气。右脉大平（或洪大、弦大）总以邪盛为要，右平则示邪未深陷或病转他经，需结合左脉及症状辨其病位在肺、在胃或在肝。", "c": [{"name": "主肺热壅盛", "desc": "右脉洪大主肺经热壅，如原文'以右脉洪大之故，痹症甚重，治在肺经'，右候肺，大为邪盛，洪为热象，故右脉大平（或洪大）反映肺经热邪壅盛，痹症由肺热所致。"}], "n": {"主肺热壅盛": 2}, "a": {"1252": "主肺热壅盛", "5453": "主肺热壅盛"}, "t": 2, "np": 0}, "pc:右+涩+弱": {"o": "右·涩弱脉总起来主阴血亏耗、热在里及本虚标实之候。其基本病机为阴血不足，脉道不充，故见涩弱；若兼数象，则示热邪内伏，形成热在里而阴已伤之局。进一步，右涩弱与左弦涩并见，则反映本虚标实、气机升降失司：肺气虚而宣发无力，肝血郁而木失条达，金不制木，木反乘金，致咳嗽、浮肿、失血等症。三类病机相互关联，阴血亏耗为共同基础，热在里为标象之一，本虚标实为整体格局，总以正虚邪恋、虚实夹杂为要。", "c": [{"name": "主阴血亏耗", "desc": "涩弱脉象示阴血不足，脉道不充。原文左脉涩弱，明言主阴血亏耗，因暑湿热内郁，误治致胃汁消亡、真阴尽烁，舌赤齿燥，邪留营中，故涩弱为阴伤日久之征。"}], "n": {"主阴血亏耗": 2}, "a": {"1299": "主阴血亏耗", "4552": "主阴血亏耗"}, "t": 2, "np": 0}, "pc:关+缓+迟": {"o": "关·缓迟脉总属脾胃虚寒、中阳不振，以关候脾胃，迟缓为阳衰阴盛、运化无力之征。其主病机可归三类：一为脾胃虚寒，见腹痛喜按、饮食不思、色现黑滞；二为里气不实，脉迟缓无力，禁下恐重虚；三为胃虚有热，关脉弱而热郁，不可大攻。三者皆以正虚为本，或寒或热为标，总不离胃气残惫、中阳不足，故治当温运扶正，慎用攻下。", "c": [{"name": "主脾胃虚寒", "desc": "关脉候脾胃，迟缓为阳不胜阴、运化无力之象。原文见关脉迟缓，按之痛止、抚摩稍适，饮食不思，色现黑滞，断为戊土残惫、中阳不振，故主脾胃虚寒、胃气衰败。"}], "n": {"主脾胃虚寒": 2}, "a": {"2171": "主脾胃虚寒", "22934": "主脾胃虚寒"}, "t": 2, "np": 0}, "pc:寸+大+疾": {"o": "寸·大疾脉总起来主燥热内盛、阳动不潜与阴液亏虚。右寸关搏而疾大，直接反映阳明燥气鼓舞，燥热内迫；燥热伤阴，肺胃阴液未充，则阳易旋动，清窍失肃，血热妄行而衄血复发。三类病机相互关联：燥热为标，阴亏为本，阳动为中间环节，共同构成阴虚燥热、阳动血溢的病理格局。脉象疾大搏指，既是燥热鼓舞之征，也是阳动不潜、阴不制阳之象，故治疗需滋清益阴以肃上，使燥热平而阳潜血止。", "c": [{"name": "主燥热", "desc": "脉右寸关搏而疾大，右寸关属肺胃，搏疾大为阳明燥气鼓舞之征。天时燥气加临，燥热内迫，故脉象疾大搏指，为燥热亢盛之象。"}], "n": {"主燥热": 1}, "a": {"2165": "主燥热"}, "t": 1, "np": 0}, "c:伏+结": {"o": "伏结脉总起来主气机郁闭与积滞内停，其形成多因惊气入于脏腑，导致气乱而郁，郁久成积。伏脉主气闭，结脉主积滞，二者并见，说明气机壅塞与有形积滞并存。原文右关伏结，右关候脾胃，惊气入脏，气机郁结于右胁，积久成形，故右胁有声如虾蟆。三类病机相互关联：惊气入脏是病因，气机郁闭是病机关键，积滞内停是病理结果。临床见伏结脉，当考虑气郁与积滞同病，治宜行气开郁、消积散结。", "c": [{"name": "主气机郁闭", "desc": "伏脉主气机郁闭，因惊则气乱，气乱则气机壅塞不通，故脉伏而不显。原文右关脉伏，结合惊气入于脏腑，说明气机郁闭是伏结脉的核心病机之一，气闭则升降失常，郁结于内。"}], "n": {"主气机郁闭": 1}, "a": {"3963": "主气机郁闭"}, "t": 1, "np": 0}, "pc:寸+弦+小": {"o": "寸·弦小脉总起来主痰积郁滞、气机不畅，兼见大肠不固之病机。其脉象弦小，弦主气郁，小主收引，反映气机郁滞、痰浊内阻；结合右寸滑、按之如黄豆大且鼓指，明确为积痰郁滞于肺。痰积上焦，肺失肃降，通调失职，则大肠之气不固，故见食后即大便。三类病机中，痰积为病之本，气郁为痰阻之果，肠虚不固为肺病及肠之标，三者相互关联，总属本虚标实、上实下虚之候。", "c": [{"name": "主痰积", "desc": "右寸滑、按之如黄豆大且鼓指，为积痰郁滞于肺之象；弦小脉反映痰阻气机，郁滞不通。原文明确'积痰郁滞于肺'，故寸弦小脉主痰积上焦，肺失肃降。"}], "n": {"主痰积": 1}, "a": {"4255": "主痰积"}, "t": 1, "np": 0}, "pc:右+弦+和": {"o": "右·弦和脉总起来主湿邪内蕴、暑湿留恋及气机郁滞三类病机。弦为气机郁滞之象，湿性黏滞易阻气机，故湿邪内蕴常见弦脉；暑必夹湿，暑湿留恋则脉数而弦，湿去则暑自消；气机郁滞既是湿阻之果，亦为弦脉直接所主。原文以“右脉弦象稍和”为湿邪暗化、郁滞稍解之征，而“数象仍然”示暑湿未尽，脉象转移与病机相应。三类病机相互关联：湿邪为病之根，气郁为湿阻之标，暑湿留恋为时令之变，总以弦脉为共同脉象特征，反映湿阻气郁、暑湿未清之候。", "c": [{"name": "主湿邪内蕴", "desc": "右脉弦象稍和，左之濡象略弦，弦濡减轻示湿邪暗化。原文以弦濡并见为湿邪内蕴之征，湿性黏滞，阻遏气机，故脉见弦；湿邪渐化则弦象稍和，说明弦脉在此主要反映湿邪内阻、气机不畅之病机。"}], "n": {"主湿邪内蕴": 1}, "a": {"4725": "主湿邪内蕴"}, "t": 1, "np": 0}, "pc:关+弦+芤": {"o": "关·弦芤脉总起来主肝胃同病，以肝旺、血虚、痰积为核心病机。弦为肝旺，芤为血虚，滑大为胃有积痰，三者相合，反映肝失疏泄、胃积痰浊、血虚不能养肝的复杂病机。其病位在肝胃，病性属虚实夹杂：肝旺与痰积为实，血虚为虚。各病机之间相互影响：肝旺克脾犯胃，胃虚生痰，痰积又加重气滞，血虚则肝体失养，肝用更亢。故治疗需制木通胃，兼顾养血化痰。", "c": [{"name": "主肝旺", "desc": "脉弦为肝旺之象，左关候肝，双弦提示肝气偏亢。原文谓‘弦为肝旺’，‘中伤木旺’，肝不疏泄则木旺，故弦脉主肝气郁结、肝阳偏亢之病机。"}], "n": {"主肝旺": 1}, "a": {"11705": "主肝旺"}, "t": 1, "np": 0}, "pc:关+弦+和": {"o": "关·弦和脉总起来主肝气横逆、气火上逆与肝阴不足三类病机。弦劲不和为肝气横逆之象，气火上逆则见咳呛胁痛、失血，而失血后肝营自虚，脉仍弦劲示肝阴不足、气火未平。三者相互关联：肝气横逆为始动因素，气火上逆为病理表现，肝阴不足为失血后的本质，共同构成肝胃络伤、气血逆乱的病机链条。", "c": [{"name": "主肝气横逆", "desc": "关脉弦劲不和，关候肝胃，弦劲为肝气横逆之象。原文谓'两关弦劲不和，肝胃络伤'，气火上逆则咳呛胁痛，脉仍弦劲示肝气未平，故主肝气横逆、胃络受伤。"}], "n": {"主肝气横逆": 1}, "a": {"11769": "主肝气横逆"}, "t": 1, "np": 0}, "pc:关+数+虚": {"o": "关·数虚脉总属本虚标实、虚实夹杂之候。数主热，虚主不足，合而观之，其热非实火，乃因虚致热。具体而言，脾土亏虚不能生金，肺气弱不能平木，遂致肝木偏强；肝强则易升火，火升又自伤肝体，形成土虚→肺弱→肝强→肝自伤的连锁病机。故脉见左关虚数、右寸虚小、关脉虚软。三类病机中，虚火为标象，脾肺气虚为本源，肝强自伤为中间环节，彼此因果相循，总以虚为本、以热为标，治当清补肺胃、培土生金以平木，不可徒事平肝伐木。", "c": [{"name": "主虚火", "desc": "脉数而虚，数主热，虚主不足，故为虚火而非实火。原文左关虚数，明言“火非实火”，乃肝体自伤、阴血亏虚所致，火性炎上而脉虚无力，属本虚标热之候。"}], "n": {"主虚火": 1}, "a": {"15926": "主虚火"}, "t": 1, "np": 0}, "pc:右+数+空": {"o": "右·数空脉总起来主肺阴亏虚、虚热内扰，兼及肺损络伤。右寸候肺，脉数主热，空为阴气不足、脉道不充，故肺阴亏虚为本，虚热为标。虚热灼肺，损伤肺络，则见咳呛痰血，形成肺损络伤之候。三类病机以肺阴亏虚为核心，虚热内扰为继发，肺损络伤为发展，层层相因，脉证相合，示肺脏已伤，病势深重。", "c": [{"name": "主肺阴亏虚", "desc": "右寸候肺，脉空为肺脉失充，阴气不足，脉道不充。原文'脉数右空'及'肺已损伤'明示肺阴耗损为本，故主肺阴亏虚。"}], "n": {"主肺阴亏虚": 1}, "a": {"18160": "主肺阴亏虚"}, "t": 1, "np": 0}, "pc:六+浮+虚": {"o": "浮虚脉总属虚候，其核心病机为正气亏虚、根本不同。从原文及下属脉总述看，浮虚脉所主主要有三：一为虚极欲脱，脉浮虚按之即无，伴汗出不止、神魂飞越，是元气外越之危象；二为虚阳外浮，真阴亏于下而阳浮于上，脉浮大虚豁，可见上热下寒或血衄；三为气阴两伤，因过汗耗气伤阴，脉见虚浮无力。三者皆以虚为本，然轻重浅深有别：气阴两伤为轻，虚阳外浮为甚，虚极欲脱最危。其共同特征是脉浮而无力、按之即无，提示无根之浮，总以固护元气、敛浮阳为要。", "c": [{"name": "主虚极欲脱", "desc": "脉浮虚按之即无，为元气外越、根本将脱之象。原文见产后过汗，六脉皆虚浮，按之即无，伴汗出不止、怔忡恍惚、神魂飞越，显系气阴两脱、虚极将脱之危候，故浮虚无根之脉主脱证。"}], "n": {"主虚极欲脱": 1}, "a": {"19826": "主虚极欲脱"}, "t": 1, "np": 0}, "pc:右+弦+芤": {"o": "右·弦芤脉总起来主气血亏极、阴阳不相维系、阳气外浮三类病机。弦为肝血不足，芤主失血，浮数无根乃阳气外浮，三者相合，反映气血亏极、阴阳不相维系之象。其核心在于阴血亏虚与阳气浮越并存，阴血亏虚为失守之根，阳气外浮为逆动之标，故见阳气上浮而面热、外越而身热，属虚劳中极危险之证。三类病机相互关联，气血亏极导致阴阳不相维系，进而阳气外浮，形成虚劳危候。", "c": [{"name": "主气血亏极", "desc": "脉左弦右芤，浮数无根，为气血亏极之象。弦为肝血不足，芤主失血，浮数无根乃阳气外浮，故气血亏极，阴阳不相维系。"}], "n": {"主气血亏极": 1}, "a": {"20384": "主气血亏极"}, "t": 1, "np": 0}, "pc:关+涩+弱": {"o": "关·涩弱脉总起来主虚，包括胃气虚、阴阳俱虚、里气不实，并可兼见虚热。其核心病机是正气不足，故凡见涩弱无力之脉，多属虚象，不可妄行攻下，以免重虚。各分类之间相互关联：虚为根本，虚热为虚中夹热，里气不实为虚在里，均强调正虚不耐攻伐。", "c": [{"name": "主虚", "desc": "关脉弱为胃气虚，尺脉涩弱无力为里气不实，脉微而恶寒为阴阳俱虚，皆正气不足之象，故涩弱脉主虚，不可攻下。"}], "n": {"主虚": 1}, "a": {"22934": "主虚"}, "t": 1, "np": 0}, "pe:六+结": {"o": "结脉总属气机阻滞、脉道不利之象，所主病机以实邪壅塞为核心，包括气滞、痰阻、寒滞及邪实内结等。原文五段中，或见六脉见结因郁怒气滞，或六脉俱结因痰寒塞滞经脉隧道，或结而有力因痰积胶固，均示气血痰食寒邪阻滞脉道，使脉气结而不畅。诸类之间相互关联：气滞可生痰，痰阻可加重气滞，寒滞则凝泣血脉，邪实壅塞为共同归宿。虽偶有正虚一面，如土虚、三虚一实，但脉结所直接反映者仍为邪实阻滞，故治疗多先治其实，行气、逐痰、散寒、通闭，使脉道通利则结脉自解。", "c": [{"name": "主气滞", "desc": "结脉主气机郁滞，脉气结而不畅。原文见六脉见结，因郁怒之余又当盛夏，气机壅滞，小便不通，气高而喘，用枳壳、生姜行气散结而愈，说明结脉反映气滞不行之病机。"}, {"name": "主痰阻", "desc": "结脉主痰浊壅滞脉道。原文见六脉俱结，且有块痰，寒滞经脉隧道，或痰积胶固，六脉结而有力，发为颠妄，均示痰实内结、阻滞脉道，故脉气结而不畅。"}, {"name": "主邪实壅塞", "desc": "结脉主邪实内结、壅塞不通。原文见六脉俱结，正虚邪实，痰浊塞滞经脉隧道，或结而有力为实邪内结，治先治其实，说明结脉可反映邪实壅盛、脉道受阻之病机。"}], "n": {"主气滞": 1, "主痰阻": 2, "主邪实壅塞": 1}, "a": {"3796": "主气滞", "5483": "主痰阻", "5546": "主邪实壅塞", "17333": "主痰阻", "21797": "__np"}, "t": 5, "np": 1}, "pe:左+空": {"o": "左·空脉总属虚证，以阴血亏虚、脉道不充为核心病机。左脉候血，空为脉中空虚无力，故首主阴血亏少、精气内伤。由此衍生数类：阴血虚则阳失潜藏，虚阳上浮，见阳浮不潜；气不足则脉空，气浮于外则脉浮，见气虚不固；肝失濡养则虚风内动，见舌强肢软；正虚而邪气留恋，则成正虚邪恋之候。各类之间以正虚为本，或纯虚，或虚中夹实，总不离「空」为根本空虚之象。其脉形虽或兼大、兼弦、兼浮，然按之不实，外强中干，故辨证当以虚为核心，兼顾所兼之邪。", "c": [{"name": "主阴血亏虚", "desc": "左脉候血，空为脉道不充、阴血不足之明征。原文见久疟伤阴、冬春温邪劫阴，致色消肉烁、气口空搏；又左脉空搏而阳不潜伏，咳吐涎沫，皆阴液损伤、阳愈炽之候。空搏无力，正是精血亏少、脉道空虚之象。"}, {"name": "主阳浮不潜", "desc": "左脉空搏而不敛，是阳气不能潜伏归根，虚阳上浮。原文「左脉空搏，阳不潜伏，咳吐涎沫」，阳不潜藏则津液不布，聚为涎沫。空为根本空虚，搏为虚阳外鼓，故主阳虚浮越、根本不固之病机。"}, {"name": "主虚风内动", "desc": "左脉空而肝失濡养，可致虚风内动。原文「脉左大右濡，肝风震动，阳明脉空，舌强肢软」，左大乃肝风震动，右濡为阳明脉空、气血不充。空脉示络脉空虚，肝风乘虚扰动，故见舌强肢软，主阴血亏虚、虚风内动之候。"}], "n": {"主阴血亏虚": 1, "主阳浮不潜": 1, "主虚风内动": 1}, "a": {"890": "主阴血亏虚", "4582": "主阳浮不潜", "5008": "主虚风内动"}, "t": 3, "np": 0}, "pe:右+短": {"o": "右短脉总以气机短缩不利为核心，所主病机涉及气虚、气郁、湿郁、虚热、血瘀等多类。短脉主气损气郁，右脉候气，故右短脉首先反映正气不足或气机郁滞；气虚则脉道不充，气郁则脉道不畅，二者常相兼为病。湿郁困阻气机，虚热耗伤气阴，血瘀营络郁滞，皆可致脉道短缩。各病机之间相互关联：气虚为根本，气郁为关键，湿、热、瘀为病理产物，虚中夹郁、郁中兼虚，故临证当于短脉中细辨虚实寒热，不可一概而论。", "c": [{"name": "主气虚", "desc": "短脉主气损，右脉候气，故右短脉多示正气不足。如案15心脉短、尺脉小示心气亏虚、肾气亦弱；15637右脉耎短按之不足为脾虚气弱，皆因气弱不能充盈脉道而见短。"}], "n": {"主气虚": 2}, "a": {"12439": "主气虚", "15637": "主气虚"}, "t": 2, "np": 0}, "pe:尺+疾": {"o": "尺·疾脉总起来主热盛、正虚邪陷、津伤火旺及胃气败绝等病机。疾脉以脉来急疾为特征，核心为热邪亢盛，气血运行加速；若兼脉体细小，则示正气虚衰、邪气内陷，或热盛伤津、阴亏火旺；若疾而散乱无根，则为胃气败绝之死候。各类之间，热盛为基本病机，正虚邪陷与津伤火旺多由热盛发展而来，而胃气败绝则是病情危重、阴阳离决的终末表现。临证须结合脉之大小、浮沉及兼象，以判吉凶。", "c": [{"name": "主热盛", "desc": "疾脉主热盛，因热邪亢盛，气血运行加速，故脉来急疾。原文如'温病时行大热，其脉细小者死'，从反面说明大热之病脉宜大疾，若细小则正不胜邪；又'尺脉躁疾，水中火发'，躁疾为火象，主热盛。"}], "n": {"主热盛": 2}, "a": {"21824": "主热盛", "24942": "主热盛"}, "t": 2, "np": 0}, "pe:关+短": {"o": "关·短脉总属阳气不足、阴寒内盛之候。其核心病机为阳虚阴盛，寸脉短少力弱提示上焦阳气不能充达，关部短少则中焦阳气亦弱，故见胸膈满闷、腹中胀满、身体拘急、手足厥冷等症。短脉主气病，气机不畅则寒凝，与沉迟紧等脉并见，更确证胃中寒。两类病机相互关联：阳虚为根本，阴盛为标象，胃中寒为具体表现。治当温中散寒、扶阳抑阴，如韩氏温中汤之类。", "c": [{"name": "主阳虚阴盛", "desc": "原文指出寸脉短少及力少于关尺，寸主上焦阳气，短少力弱为阴盛阳虚、阳不上充。阳虚不能温煦，故见胸膈满闷、腹中胀满、身体拘急、手足厥冷等寒凝之症，治宜温中。"}], "n": {"主阳虚阴盛": 1}, "a": {"24237": "主阳虚阴盛"}, "t": 1, "np": 0}, "ps:左关+大": {"o": "左关大脉总属肝经病机，以邪实为主，兼有虚实夹杂。其大象多因肝火亢盛、气郁化火、痰瘀壅聚、湿热内蕴等实邪鼓动气血所致，故常兼弦、数、滑、洪等脉。然亦有阴亏阳浮、虚阳不敛之虚证，脉大而按之不摄。各类之间，实热与郁火常相兼，痰瘀与湿热多互结，虚阳则因实邪耗阴或素体亏虚而致。总以左关候肝，大脉提示肝经气血壅盛或阳浮不敛，临证须合兼脉及症候，辨其虚实寒热。", "c": [{"name": "主肝火", "desc": "左关候肝，脉大而兼弦、数、洪，为肝经阳热亢盛之象。原文如“左关脉洪大”主齿痛连太阳，“左关独大或见弦数”主肝火不得卧，“左关洪大”为肝火之诊，皆因火性炎上，故见头痛、齿痛、不寐等症。"}, {"name": "主郁热", "desc": "脉大而弦，弦主气郁，大主邪盛，为肝郁化火、气机壅滞之征。原文如“左关弦大”主温燥内郁、肝火上炎，“左关弦大”主暑湿交蒸、肝胃失和，皆因郁久化热，热势张扬故脉大。"}, {"name": "主痰瘀", "desc": "脉大而弦滑或鼓指，弦主气郁，滑主痰凝，大主邪实壅聚。原文如“左关弦大而滑”主木郁痰凝之石疽，“左关弦大”兼右寸滑大主老痰瘀血积于上焦，皆因痰瘀互结，气血壅遏，脉道充盈而现大象。"}, {"name": "主虚阳", "desc": "脉大而弦，按之不摄，为阴亏阳浮、虚阳上亢之象。原文如“左关尺脉弦大不摄”主真阴素亏、肾虚肝逆之奔豚，“左关脉大”主阴涵不足、阳升有余之头痛，皆因阴不制阳，阳气浮越，脉道扩张而大。"}, {"name": "主湿热", "desc": "脉大而弦，独见于左关，为肝经湿热偏盛之征。原文如“左关脉息独大独弦”主肝肾湿热所伤、精房不固，余脉细小示肾精亏虚，弦大为湿热壅滞之实象，故独显于关部。"}, {"name": "主半表半里", "desc": "脉大而数或弦，见于左关，为邪居表里之间、枢机不利之象。原文如“左关数大下连乎尺”主太阳半表半里，“左关独弦”主少阳半表半里，皆因邪正交争，气血壅盛于关部，故脉大而数。"}], "n": {"主肝火": 7, "主郁热": 2, "主痰瘀": 2, "主虚阳": 2, "主湿热": 4, "主半表半里": 1}, "a": {"2140": "主肝火", "2180": "主肝火", "3094": "主郁热", "3291": "主郁热", "6116": "主湿热", "6207": "主肝火", "6411": "主湿热", "6460": "主痰瘀", "6502": "主肝火", "6956": "主虚阳", "7097": "主肝火", "7403": "主湿热", "7724": "主虚阳", "9058": "主湿热", "15036": "主痰瘀", "24916": "主半表半里", "24924": "主肝火", "25038": "主肝火"}, "t": 18, "np": 0}, "ps:右寸+小": {"o": "右寸小脉总主痰湿、气火、虚损及脾弱。小脉为气血不足或邪阻之象，右寸候肺，肺主气，通调水道，故小脉多反映肺气不宣、痰湿内阻；又肺朝百脉，肝火犯肺、气火上升亦见小弦而数；久病肺金亏损，气阴两伤则见小涩或细数而小滑；脾为生痰之源，脾弱湿生，上贮于肺，故右寸关小脉亦主脾弱湿浊。各类之间常相兼夹，如痰湿与气火互结，虚损与痰湿并存，总以本虚标实、虚实夹杂为特点。", "c": [{"name": "主痰湿", "desc": "右寸小脉多主痰湿内蕴。原文如案31见右寸关小弦而数，体肥多湿多痰，湿浊灌塞；案7655右寸小涩，关部带滑为痰；案10901右寸细数而小滑，小滑为痰；案15518右寸软小不疏，关滑数，痰火不易出。小脉示痰湿阻滞，气机不畅。"}, {"name": "主气火", "desc": "右寸小脉亦主气火内郁。案31右寸关小弦而数，肝家气火多升少降；案7655左寸关俱弦，肝火上犯，咳剧吐秽痰；案10901右寸细数而小滑，数为伏火；案15518右寸软小不疏，气有余便是火，火即无形之痰。小脉反映气火郁结，升降失常。"}, {"name": "主虚损", "desc": "右寸小脉可主肺金虚损或气阴不足。案7655右寸小涩主肺金久损；案10901右寸细数而小滑，细为阴伤；案15518右寸软小不疏，软小濡小为气火虚。小脉示正气亏虚，肺气不足或阴伤。"}, {"name": "主脾弱", "desc": "右寸小脉关联脾弱湿生。案31右寸关小弦而数，脾胃湿浊尚盛，脾不运行；案2660右寸关小数，脾弱湿生，湿阻中室，真阳不运。小脉示脾虚不运，湿浊内停。"}], "n": {"主痰湿": 2, "主气火": 1, "主虚损": 1, "主脾弱": 1}, "a": {"2659": "主痰湿", "2660": "主脾弱", "7655": "主痰湿", "10901": "主气火", "15518": "主虚损"}, "t": 5, "np": 0}, "pp:两尺": {"o": "两尺脉总主下焦肾与膀胱病机，以肾虚为核心，兼及寒热虚实。其病机可归纳为肾虚、虚寒、湿热、热盛火旺、阴虚火旺、寒凝血瘀、气结邪实、正虚邪恋八类。肾虚与虚寒多因尺脉无力，主阴阳精血亏虚或阳气衰微；湿热、热盛火旺、气结邪实多因尺脉有力，主邪热壅盛或气机壅滞；阴虚火旺为虚火，脉多细数或洪数中取不见；寒凝血瘀为寒实，脉多紧涩；正虚邪恋为虚实夹杂，脉多虚中夹实。各类之间可相互转化，如肾虚日久可致虚寒，湿热久蕴可化火伤阴，寒凝血瘀可兼正虚。临证当结合脉之有力无力、兼脉及症候，辨其虚实寒热。", "c": [{"name": "主肾虚", "desc": "两尺候肾，脉见沉、细、微、弱、虚、涩、小等无力之象，多主肾之阴阳精血亏虚。如两尺沉细主肾阴亏虚，沉微主肾气阴血不足或真阳衰微，细弱无力主肾阳虚衰，虚细主肝肾两虚、精血不足，涩小主精血亏少。原文屡言‘少阴久虚’‘肾阴亏虚’‘肾元虚’‘先天阴阳俱虚’，皆以尺脉无力为据。"}, {"name": "主虚寒", "desc": "两尺脉见沉、紧、微、伏、细弱等象，主下焦虚寒、阳气衰微。如两尺沉紧主虚寒内盛、痰饮寒凝；两尺全伏主肾阳衰微、阴寒内盛，阳气不能布达；两尺微细主肝肾两虚、重寒深湿著于筋骨；两尺细弱无力主脾肾阳虚、寒邪作祟。原文多伴足冷、舌苔灰黑、哕声近呃等虚寒之症。"}, {"name": "主下焦湿热", "desc": "两尺脉见滑、数、洪、濡数、坚搏等象，主湿热壅遏下焦。如两尺滑主湿热积滞下焦，小便不利、大腹胀满；两尺濡数主湿温阴伤；两尺坚搏主素蕴湿热聚于下焦，膀胱气化不行；两尺洪盛主肾气传膀胱，气结为石块。原文多伴溺涩、腹胀、淋秘等症，脉象有力或兼濡。"}, {"name": "主热盛火旺", "desc": "两尺脉见洪、数、大、滑而有力，主下焦实热或相火偏旺。如两尺洪大且数主热毒炽盛、气血壅滞，或阴火太旺、水亏火炎；两尺洪滑有力主相火偏旺；两尺数主肾与膀胱有火；两尺洪盛主邪实火旺。原文多伴疮毒、遗泄、耳鸣、足跟痛等症，脉象洪数有力。"}, {"name": "主阴虚火旺", "desc": "两尺脉见细数、数大无力、洪数而中取不见，主肾阴亏虚、虚火内动。如两尺细数主肾水枯涸、虚火上炎；两尺数主水亏火动、肾失封藏而遗泄；两尺洪大且数、中取不见主阴火太旺、水亏火炎；两尺细数或浮大主肾痹，水衰火动。原文多伴遗泄、耳鸣、腰膝酸软、舌音不清等症。"}, {"name": "主寒凝血瘀", "desc": "两尺脉见紧、涩、沉紧而搏手，主寒邪客于下焦，血为寒凝，瘀阻不通。如两尺紧而涩主寒伤营血，瘀血归于大肠，痢下黄黑而痛；两尺沉紧坚搏主下焦冷极，胎已无气；两尺紧无力主寒湿凝滞、气血壅阻，臀痈坚硬肿痛。原文多伴疼痛、痢下、癥块等症，脉紧涩有力或兼无力。"}, {"name": "主气结邪实", "desc": "两尺脉见洪盛、实、坚搏等象，主邪实内结、气机壅滞。如两尺洪盛主肾气传膀胱，气结为石块，非血块；两尺皆实主胎孕，外受风邪搏激；两尺坚搏主湿热壅结下焦，膀胱气化不行。原文多伴少腹硬块、溺闭、腹胀等症，脉实有力，提示邪气壅盛而非正虚。"}, {"name": "主正虚邪恋", "desc": "两尺脉见虚细、弦而虚细、紧而无力等象，主正气不足，邪气留恋。如体虚受邪，寒热久羁，脉弦两尺虚细，主肾气亏虚、正虚邪恋；臀痈肿痛，两尺紧而无力，主下焦气血不足、邪毒凝滞，正虚不能托毒；虚人外感，尺脉虚细，宜补中益气汤加减。原文强调正虚为本，邪恋为标，脉象虚中夹实。"}], "n": {"主肾虚": 12, "主虚寒": 7, "主下焦湿热": 4, "主热盛火旺": 6, "主阴虚火旺": 9, "主寒凝血瘀": 4, "主气结邪实": 7, "主正虚邪恋": 5}, "a": {"63": "主阴虚火旺", "2018": "主阴虚火旺", "2175": "主肾虚", "2179": "主热盛火旺", "3496": "主寒凝血瘀", "3922": "主肾虚", "3974": "主气结邪实", "3975": "主气结邪实", "4034": "主气结邪实", "4063": "主气结邪实", "4316": "主气结邪实", "6143": "主正虚邪恋", "6194": "主热盛火旺", "6239": "主阴虚火旺", "6438": "主正虚邪恋", "6489": "主热盛火旺", "6532": "主阴虚火旺", "8380": "主气结邪实", "8390": "主下焦湿热", "8449": "主寒凝血瘀", "9134": "主阴虚火旺", "12111": "主虚寒", "12112": "主虚寒", "12162": "主下焦湿热", "12257": "主阴虚火旺", "13656": "主下焦湿热", "14774": "主下焦湿热", "15053": "主虚寒", "15256": "主肾虚", "16149": "主虚寒", "16234": "主热盛火旺", "16237": "主寒凝血瘀", "16239": "主寒凝血瘀", "17033": "主正虚邪恋", "18199": "主气结邪实", "18339": "主肾虚", "18340": "主肾虚", "19460": "主热盛火旺", "19584": "主肾虚", "19957": "主虚寒", "20409": "主肾虚", "20460": "主肾虚", "20703": "主肾虚", "24269": "主正虚邪恋", "24285": "主正虚邪恋", "24638": "主阴虚火旺", "24754": "主肾虚", "24801": "主肾虚", "24818": "主阴虚火旺", "24967": "主阴虚火旺", "25032": "主肾虚", "25103": "主热盛火旺", "25605": "主虚寒", "27217": "主虚寒"}, "t": 54, "np": 0}, "rc:沉取+大+虚+洪": {"o": "沉取·大虚洪脉总起来主两类病机：一为实热，一为虚热。实热者，脉洪大滑数、重按有力，主暑热内盛，如阳明热盛之白虎汤证；虚热者，脉洪大而虚、重按全无，主血虚发热或气血俱虚，因阴血亏虚、阳气浮越，证象白虎而脉不长实。两类脉象虽同见洪大，但以重按有力无力为辨：有力为实，无力为虚。虚证又因病因不同，或为血虚，或为气血俱虚，然皆属虚阳外浮，误作实热则危。故临床须细辨脉之虚实，不可见洪大即投寒凉。", "c": [{"name": "主暑热内盛", "desc": "脉洪大滑数、重按有力，为暑热内盛之象。原文赵子升夏病疟，孟英断为“暑热为患”，予白虎汤清解暑热。洪大滑数主阳明热盛，故用石膏知母；若脉洪大为阴虚，则温疟用白虎加桂枝，湿热疟用白虎加苍术，皆从脉辨治。"}, {"name": "主血虚发热", "desc": "脉洪大而虚、重按全无，为血虚发热之候。原文强调“脉不长实有辨耳”，洪大似热盛，然虚而重按无根，是阴血亏虚、阳气浮越，非实热白虎证。得于饥困劳役，证象白虎而脉虚，误服白虎汤必死。"}, {"name": "主气血俱虚", "desc": "脉洪大而虚、重按全无，亦主气血俱虚。原文治疮疡脾胃虚损，或服峻剂致血气俱虚，肌热大渴引饮，目赤而红，昼夜不息。洪大似实热，然重按全无则中空，为血气俱虚、虚阳外浮之候，误服白虎汤必死。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主暑热内盛": 1, "主血虚发热": 2, "主气血俱虚": 1, "其他": 0}, "a": {"13954": "主暑热内盛", "19335": "主血虚发热", "24290": "主气血俱虚", "27137": "主血虚发热"}, "t": 4, "np": 0}, "pc2:右关+滑+洪": {"o": "右关洪滑脉总属痰热壅盛、实邪内结之候。洪为热盛，滑为痰浊，右关候中焦脾胃，故其主病以中焦痰热为核心。四类病机相互关联：痰热壅滞中焦可致实积内结，痰热与瘀血相合则成瘀血痰积，痰火上扰心包则神昏乱语。原文八段中，或单见洪滑主痰热，或兼涩主瘀血，或兼数大主痰火扰神，或有力主实积，皆以洪滑为痰热实邪之共同基础。要之，此脉主痰、主热、主实，邪盛而正未大虚，治多从清化痰热、行气开郁、通滞攻积入手。", "c": [{"name": "主痰热", "desc": "右关洪滑脉象直接反映中焦痰热壅盛。原文如4027段言'洪滑主痰热'，4328段'右关洪滑主痰热壅滞中焦'，6014段'右关洪滑主痰浊壅盛于中'，均以洪滑为痰热内蕴之征，症见胸膈胀闷、吐痰不已、舌苔厚等。"}, {"name": "主实积", "desc": "洪滑有力主实热积滞内结。6133段'洪滑主痰热实积'，6428段'右关洪滑、两尺有力，主中焦痰热积滞'，症见右胁块起疼痛拒按、便结、日夜不睡，脉象有力示邪实壅盛，故用攻下通滞之法。"}, {"name": "主瘀血痰积", "desc": "洪滑兼涩主胃中瘀血与痰积并存。6023段'洪滑主胃中痰热，涩主瘀血阻滞'，6317段'右关洪滑主胃中痰积，左手涩主血行不畅、瘀血内停'，症见咳喘吐痰、胸胀、便下紫黑血，脉症合参为瘀血痰积。"}, {"name": "主痰火扰神", "desc": "洪滑数大主痰火壅盛、蒙蔽心窍。4027、4328、6014、6308段均载右关洪滑兼左寸洪数、两尺洪大，症见昏冒、咬牙乱语、口噤、手心热，原文谓'痰迷心窍''痰热在心包络'，洪滑数大为痰火内扰之象。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主痰热": 4, "主实积": 2, "主瘀血痰积": 2, "主痰火扰神": 0, "其他": 0}, "a": {"4027": "主痰热", "4328": "主痰热", "6014": "主痰热", "6023": "主瘀血痰积", "6133": "主实积", "6308": "主痰热", "6317": "主瘀血痰积", "6428": "主实积"}, "t": 8, "np": 0}, "pc2:右寸+数+浮": {"o": "右寸浮数脉总以肺系病变为核心，浮主表、主风，数主热，合而多主风热、燥火等外邪犯肺之实热证；然脉症合参，浮数亦可见于脾土亏损、虚阳外浮之虚火，以及湿火下注、相火不静之虚实夹杂证。各类之间，风热、燥火偏于外感实邪，虚火、湿火则涉内伤虚实。右寸候肺，故病位多在肺，但可兼及脾胃、肝肾。临证须结合兼脉及症状，辨其虚实，不可一见浮数即投清利。", "c": [{"name": "主风热", "desc": "右寸浮数，浮主风邪在表，数主热，合为风热客肺之象。如案23咽喉碎烂甚于右，脉右寸浮数，究属风热上感；又案目白珠红未退，右寸浮数，为肺有风热，风热循经上攻，故主风热表证。"}, {"name": "主虚火", "desc": "浮数非尽实热，亦可为虚阳外浮。如案感冒发表后咳喘食少，右寸关浮数，王宇泰断为脾土亏损、不能生肺金，虚火上浮之征；若更通利耗津，必成肺痈，故浮数在此主脾虚肺损、虚火。"}, {"name": "主燥火", "desc": "浮为燥邪在表，数为燥热伤津。原文燥火呕吐之脉，右寸浮数，主燥邪伤肺；右关数大，主燥邪伤胃。寸关分部定位，说明浮数属肺，为燥火伤肺之脉象。"}, {"name": "主湿火", "desc": "浮数亦可主湿火下注。如案小溲频涩、溺后窍底酸疼刺痛，脉右寸关浮数，左关尺虚数，断为湿火下注，兼相火不静，从肺肝肾三经论治。浮数示湿火蕴结，虚数示阴精亏虚、相火妄动。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主风热": 3, "主虚火": 1, "主燥火": 1, "主湿火": 1, "其他": 0}, "a": {"4118": "主风热", "4344": "主虚火", "14991": "主风热", "15499": "主风热", "15629": "主湿火", "24842": "主燥火"}, "t": 6, "np": 0}, "pc2:两关+弦+细": {"o": "两关弦细脉总以肝旺阴伤为基本病机，弦主肝木偏亢，细主营血不足或阴伤，两关候肝脾，故其病机多围绕肝脾关系展开。具体可分四类：一为肝旺，肝气横逆、风木偏亢；二为阴伤，营血亏耗、气结阴亏；三为肝脾不和，肝强脾弱、木郁土虚，气机壅滞而痰湿内阻；四为暑湿郁遏，邪热内扰而阴已伤。四类之间常相互兼夹，如肝旺与阴伤并见，肝脾不和与痰湿同存，暑湿郁遏则邪未透而正已伤。总属本虚标实、肝脾同病之候。", "c": [{"name": "主肝旺", "desc": "弦为肝木偏亢之象，两关候肝脾，弦脉独见于关，提示肝气横逆、肝木旺时痛痢日剧。如原文“弦为肝木偏亢”“弦为肝旺”，皆以弦主肝气偏亢、横暴之气郁怒冲突。"}, {"name": "主阴伤", "desc": "细为营血不足、阴伤之征。原文“细为营血不足”“细为阴伤”，两关弦细并见，示肝旺而阴血亏耗，气结阴亏，常见于痛泄日久、噎膈等病。"}, {"name": "主肝脾不和", "desc": "两关候肝脾，弦细并见为肝气横逆而犯胃土、肝强脾弱。原文“肝气犯胃”“土制于木”“肝脾不和、木郁土虚”，症见胸咽梗痛、脘闷嗳气、呕酸痰、便秘等。"}, {"name": "主暑湿郁遏", "desc": "弦为暑湿郁遏肝脾，细为阴伤，不静乃邪热内扰。原文“弦为暑湿郁遏肝脾，细为阴伤，不静乃邪热内扰”，暑湿内蕴未经疏解，误投温补滋腻，致邪未透而正已伤。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主肝旺": 2, "主阴伤": 0, "主肝脾不和": 1, "主暑湿郁遏": 1, "其他": 0}, "a": {"7790": "主肝旺", "12736": "主肝旺", "15595": "主暑湿郁遏", "15695": "主肝脾不和"}, "t": 4, "np": 0}, "rs:浮取+虚": {"o": "浮取·虚脉总属正气不足、脉道不充之象，其病机以虚为本，但常兼夹实邪。从所收段落看，虚脉可主阳气衰弱，因阳气不能舒伸而伏匿于阴中，脉虽弦而按之虚；可主湿邪内盛，湿困阳气、泄利体重，脉见弦虚；可主阴血亏虚，阴血不足则脉道不充，按之细弱；亦可主痰热互结，痰热内蕴而正气已伤，脉见滑大软滑而按之虚。四类病机中，阳气衰弱与湿邪内盛常相兼为患，阴血亏虚与痰热互结亦多并见，总以正虚邪实、虚实夹杂为特点。虚脉虽主虚，但需结合兼脉及症候，辨明所兼夹之邪，方能全面把握病机。", "c": [{"name": "主阳气衰弱", "desc": "原文谓“弦脉令虚多言之故”“阳气衰弱，不能舒伸，伏匿于阴中”，指出脉虽弦而按之虚，乃阳气虚衰、不能舒展，故见气短、精神不足、视听半失等症。虚脉在此反映阳气不足、鼓动无力。"}, {"name": "主湿邪内盛", "desc": "霖雨阴寒，湿多成五泄，症见体重肢痛、大便泄泻、小便秘涩。湿邪困阻阳气，脉见弦而按虚，说明湿盛阳微、气机不伸。虚脉提示湿邪内盛而正气已伤，属虚实夹杂之候。"}, {"name": "主阴血亏虚", "desc": "尺中滑大按之细弱，右脉软滑，症见经断半年、唇白口糜、舌绛无津、耳鸣巅痛。按之细弱为阴血亏虚之象，虚脉在此反映阴血不足、脉道不充，兼痰热互结而见滑大软滑。"}, {"name": "主痰热互结", "desc": "左脉弦数上溢，尺中滑大，右脉软滑，症见胁腹聚块上窜、腹胀腿肿、暮热无眠。滑大软滑主痰热内蕴，按之细弱则示正气已虚。虚脉在此提示痰热互结而阴血耗损，本虚标实。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主阳气衰弱": 2, "主湿邪内盛": 0, "主阴血亏虚": 2, "主痰热互结": 0, "其他": 0}, "a": {"3424": "主阳气衰弱", "13277": "主阴血亏虚", "13883": "主阴血亏虚", "21797": "__np", "25216": "主阳气衰弱"}, "t": 5, "np": 1}});